    "titleTh": "The Early Spring ฤดูใหม่นี้มีเพียงสองเรา (2026) พากย์ไทย-ซับไทย",
    "titleEn": "The Early Spring ฤดูใหม่นี้มีเพียงสองเรา (2026) พากย์ไทย-ซับไทย",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/08/9-12-foxywebp.webp",
