    "videoUrl": "https://torbo007.com/embed/e62b11b594c9a9fe66e3fa59d5d79119",
    "sourceType": "embed",
    "description": "เรื่องย่อ: ฤดูใหม่นี้มีเพียงสองเรา\r\n ท่ามกลางความรักของหนุ่มสาววันทำงาน ต่างต้องแบกรับปัญหาต่างๆ และนี่เองก็เป็นอีกหนึ่งการบอกเล่าเรื่องของ “ซางจือเถา” กับ “หลวนเหนียน” ต่างมีการแบ่งแยกฐานะอย่างชัดเจน แต่แล้วความสัมพันธ์ของทั้งคู่ เริ่มกลายเป็นความรัก ที่กำลังผลิบานมากขึ้นเรื่อยๆ ซึ่งเคียงคู่กันมานานนับ 6 ปี ก่อนที่เรื่องราวทุกอย่างเริ่มแดงขึ้นเรื่อยๆ เพราะเรื่องราวเหล่านี้เองกลับทำให้ทุกอย่างกลายเป็นกำแพง ที่ผลักให้พวกเขาทั้งสองต้องถอยห่างกันอีกครั้ง ทว่า ซางจือ ที่ค่อยตัดใจถอยห่างเขามากขึ้นเรื่อยๆ แต่เมื่อทั้งสองได้กลับมาเจอกันอีกครั้ง ที่บ้านเกิดของเธอด้วยการเริ่มต้นใหม่ชีวิตใหม่ ด้วยการเปิดร้านอาหารกลางดึก พร้อมการใช้ชีวิตแบบที่ตนเองต้องการ ในขณะเดียวกันนั้นความรักครั้งเก่า ที่กำลังหวนคืนกลับมาอีกครั้ง และเรื่องราวทุกอย่างต่างต้องจบลง ด้วยการเข้าใจเอาใจใส่ พร้อมการก่อตัวของความรักครั้งใหม่ที่สมบูรณ์แบบ ทว่าเรื่องราวความโรแมนติกของพวกเขาทั้งสองคนนี้จะเป็นอย่างไรเราไปรับชมพร้อมกันต่อได้ที่ ดูซีรี่ย์G4 ที่เรานำมาเสิร์ฟให้แฟนๆได้รับชมกันถึงที่แล้ว🌸🍃✨  \r\n",
