    "videoUrl": "https://torbo007.com/embed/98514be94afde76f285aa3e8342cab93",
    "sourceType": "embed",
    "description": "เรื่องย่อ: 그대에게 드림 🌻🥦🥨\r\n ย้อนกลับไปที่ช่วงสมัยมัธยมของ “อูซูบิน” ชายหนุ่มผู้ใฝ่ฝันอยากเป็นผู้กำกับภาพยนตร์ ได้พบกับ “จูอีแจ” หญิงสาวที่มีความมุ่งมั่นและเป็นแรงบันดาลใจให้เขากล้าที่จะเดินตามความฝันของตัวเอง ทั้งสองเคยสัญญาว่าจะสร้างภาพยนตร์ร่วมกันในอนาคต แต่เมื่ออายุ 19 ปี ซูบินกลับหายตัวไปจากชีวิตของอีแจอย่างกะทันหัน ทิ้งไว้เพียงความทรงจำและคำสัญญาที่ยังไม่เคยเป็นจริง เวลาผ่านไป ซูบินทุ่มเททำงานอย่างหนักจนประสบความสำเร็จ กลายเป็นผู้กำกับภาพยนตร์อัจฉริยะที่ได้รับการยอมรับในระดับนานาชาติ หลังจากผลงานเปิดตัวของเขาคว้ารางวัลจากหลายเทศกาลภาพยนตร์ เขาจึงตัดสินใจเดินทางกลับประเทศเกาหลีใต้ เพื่อทำตามความฝันที่แท้จริง นั่นคือการกลับมาหาหญิงสาวที่เขาไม่เคยลืม ขณะเดียวกัน อีแจซึ่งเคยเป็นคนที่เต็มไปด้วยความหวัง กลับต้องยอมแพ้ต่อความเป็นจริงของชีวิต เธอละทิ้งความฝันในการสร้างภาพยนตร์ และกลายมาเป็นผู้สื่อข่าวภาคสนามที่เก่งกาจ ปรับตัวได้ดี และดูเหมือนจะใช้ชีวิตอย่างเข้มแข็ง แม้ภายในใจจะยังคงมีช่องว่างที่ไม่เคยเติมเต็ม\r\n",
