    "titleEn": "Flex X Cop 2 คุณชายสายสืบ ซีซั่น 2 (2026) พากย์ไทย-ซับไทย EP.1-14",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/08/9-1-foxywebp.webp",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/08/9-1-foxywebp.webp",
    "videoUrl": "https://torbo007.com/embed/cd414e443da71d4a55e50484622d0955",
    "sourceType": "embed",
    "description": "เรื่องย่อ: คุณชายสายสืบ ซีซั่น 2\r\n “เมื่อการกลับมาของชายหนุ่มสุดบู๊ ครั้งนี้เขากลับมาพร้อมฐานะนายตำรวจใหญ่ พร้อมภาระกิจปราบปรามเหล่าอาชญากรรม” ในครั้งนี้เขาจะพาคนดูไปพบเจอกับความจริงบนดลกของเรา เป็นอีกหนึ่งการเล่าเรื่องราวต่อของ “จินอีซู” หนุ่มทายาทตระกูลมหาเศรษฐีที่เอาแต่ใจ ครั้งนี้เขากลับพร้อมเข้ามาพลิกชีวิตบทบาทใหม่ ในฐานะตำรวจหนุ่มในฝ่ายสืบสวน เมื่อความมุ่งมั่นทุกอย่างกลับทำให้เขา เลือกเดินทางครั้งใหม่แต่แล้วทุกอย่างกลับไม่ได้ง่ายอย่างที่เขาคิดเอาไว้ ในเมื่ออดีตครูฝึกสุดเข้มงวดที่เคยทำให้ชีวิตเขาพังอย่างสาหัส แต่แล้วการก้าวเดินทางของเขากลับทำให้ก้าวเข้ามาเป็นหัวหน้าหน่วยฝึกสอนคนใหม่ของทีมสืบสอนอาชญากรรม และเรื่อวราวความวุ่นวายจึงได้เริ่มต้นขึ้น เมื่อทั้งสองคนต้องกลายมาเป็นคู่หูที่ต้องร่วมงานเคียงข้างกัน ในความสนุกของซีรี่ย์เรื่องนี้กลับขาดใครไปไม่ได้เลยนอกจาด นโบฮยอน พร้อมสตรีมครั้งแรกบนช่องทาง Disney+ ที่มาในแนว ซีรี่ย์อาชญากรรมเกาหลี คอมเมดี้ และการเล่าเรื่องราวของชายหนุ่มสุดก๋วน และความสนุกของเรื่องสามารถรับชมตอนแรก พร้อมกันได้ในวันที่ 7 สิงหาคม 2026 จำนวน 14 ตอนเท่านั้น เพื่อนๆคน-หนที่ยังไม่มีแอบบอกเลยว่าไม่ต้องเสียใจไป เพราะช่องทาง G4 ได้งัดนำความสนุกมาไว้ตรงนี้แล้ว     \r\n",
