    "sourceType": "embed",
    "description": "เรื่องย่อ: ศิษย์พี่อย่าเคร่งนักเลย\r\n เรื่องราวการผจญภัยแห่งเมืองโบราณ ที่เต็มไปด้วยความลึกลับและความตื่นตาตื่นใจ บอกเล่าเรื่องราวของ หลี่ฉางโซ่ว ชายหนุ่มที่กำลังอยู่ในอาการปาวยหนักปางตาย ทว่าเมื่อเขาได้รับโอกาศมีชีวิตกลับคืนมาอีกครั้ง พร้อมการตั้งมั่นแก่การบำเพ็ญเพียร และไม่วุ่นวายกับผู้คนทั่วไป ครั้งนี้เขากลับพยายามฝึกตนให้เป็นเซียนและมีชีวิตเพื่องการอยู่รอดให้ถึงที่สุด เพราะรู้ว่าดลกแห่งการบำเพ็ยเพียรเต้มไปด้วยอันตราย หลี่ฉางโซ่ว จึงยึดหลัก “ปลอดภัยไว้ก่อน” อย่างเคร่งครัด เขาไม่ชอบสร้างปัญหา ไม่ยุ่งกับเหตุและผลที่ไม่จำเป็น ซ่อนความสามารถที่แท้จริง เตรียมแผนหลบหนีไว้ล่วงหน้า รวมถึงศึกษาการปรุงยาและพิษเพื่อใช้รับมือศัตรู แต่เดิมทีเขาพยายามเข้ามาฝึกฝนเก็บตัวเป็นเซียนอย่างเงียบๆ บนภูเขา ไม่ข้องเกี่ยวกับเรื่องราวของผู้คนภายนอก แต่ชีวิตอันแสนสงบกลับต้องเปลี่ยนไป เมื่ออาจราย์ของเขารับ (ศิษยืน้องหญิงคนใหม่) เข้ามา ทำให้แผนการใช้ชีวิตอย่างระมัดระวัง หลี่ฉางโซ่ว เริ่มพังลงมากอย่างไม่เป็นท่า เพราะเหตุนี้เองกลับทำให้เหตุการณืเล็กๆ จึงค่อยๆ ลุกลามจนเขาต้องเข้ามายุ่งเกี่ยวกับเหตุการณ์ ของเห่าเซียน เผ่ามังกร และขั้วอำนาจต่างๆ โดยที่เข้าตัวพยายามหลบหลีกการใช้ กลยุทธ์ และการวางแผน เพราะเหตุนี้เองกลับทำให้เองกลับทำให้เขายิ่งลำลึกเข้ามาพังพันกับเหตุการณ์ครั้งใหญ่ จนกกลายเป็นการชักใยผู้อยู่เบื้องหลัง จากหลายๆเหตุการณ์โดยไม่รู้ตัว ทั้งความสัมพันธ์กับผู้คนรอบข้างก็เริ่มซับซ้อนมากขึ้นเรื่อยๆ โดยเฉพาะเมื่อทั้งสองมีศัตรูและหญิงสาวมากมายเข้ามาในชีวิต และนี่เองจึงเป็นเรื่องราวการผจญภัยของ ศิษย์พี่ผู้แสนระมัดระวัง ที่มีชายหนุ่มอยากใช้ชีวิตอันเงียบสงบ แต่กลับต้องมารับมือกับเหตุการณ์ระดับสะเทือนฟ้า พร้อมมุมตลกและการแก้แค้นในเวลาเดียวกัน\r\n",
