    "description": "เรื่องย่อ: หงส์คืนบัลลังก์แค้น | 鳳池生春\r\n เป็นอีกหนึ่งเรื่องราวของ “ฉีหยวน” บุตรสาวที่แท้จริงของสำใหญ่อย่างจวนโหว ผู้ถูกสลับตัวตั้งแต่แรกเกิด จนกระทั่งเติบโตมาในฐานะลูกสาวของครอบครัวคนขายเนื้อ ในขณะเดียวกันนั้นอีกคนใช้ชีวิตอย่างสุขสบายในฐานะคุณหนูผู้สง่างาม เมื่อความจริงเริ่มเปิดเผยขึ้นมาเรื่อยๆ หญิงสาวที่เข้ามาสวมรอย ว่าเป็นฐานะของตนจะถูกแย่งคืน จึงวางแผนใส่ร้ายและเหยียบย่ำ “ฉีหยวน” ทุกวิถีทางแต่แล้วทุกอย่างกลับให้เธอต้องเผชิญหน้ากับการดูหมิ่น การทรยศ และถูกบีบบังคับให้กลายเป็นองค์รักษ์ลับของ “องค์ชายเซียวอวิ๋นถิง” ระหว่างการร่วมกันฝ่าฟันอันตราย ทั้งสองต่างค่อยๆเริ่มก่อตัวเป็นความรักกลางเกมอำนาจที่ซับซ้อนเหล่านี้ แต่ในค่ำคืนวันแต่งงาน กลับเกิดเหตุการณ์ที่น่าเศร้ากลับมาอีกครั้ง เมื่อองค์ชายฉีบุกเข้ามาทำลายทุกสิ่ง แต่แล้วทั้งสองต่างจบชีวิตไปอย่างกระทันหัน ทว่าโชคชะตากลับมอบโอกาสให้เธอได้ย้อนเวลากลับมาอีกครั้ง พร้อมความทรงจำครั้งเก่า ในการเกิดใหม่ครั้งนี้ทำให้ “ฉีหยวน” ไม่ยอมตกเป็นเหยื่อของผู้มีอำนาจอีกต่อไป พร้อมการวางแผนทวงคืนความยุติธรรมคืน ในครั้งนี้เธอมาพร้อมกับการเปิดโปรงคนที่เคยหักหลัง และการล้างแค้นทุกคนที่เข้ามาทำลายชีวิตของเธอ พร้อมทั้งต่อสู้เพื่อปกป้องคนที่และเปลี่ยนชะตากรรมอันโหดร้ายให้กลายเป็นอนาคต ที่สามารถเลือกเดินสุ่เส้นทางตนเองได้ สุดท้ายแล้วจุดจบของซีรี่ย์เรื่องนี้จะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ\r\n",
