    "titleTh": "Mousetrap กับดักจับลวง (2026) พากย์ไทย EP.1-10",
    "titleEn": "Mousetrap กับดักจับลวง (2026) พากย์ไทย EP.1-10",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/07/1-9.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/07/1-9.jpg",
    "videoUrl": "https://torbo007.com/embed/2750a2bae6f987970ac92f86843591e8",
    "sourceType": "embed",
    "description": "เรื่องย่อ: กับดักจับลวง\r\n บอกเล่าเรื่องราวของ มุนแจ หนุ่มนักเขียนนิยายผู้ใช้ชีวิตอย่างสันโดษ และเก็บตัวมานาน ต้องเผชิญหน้ากับเหตุการณ์ต่างๆ ทั้งเรื่องราวที่เหนือความคาดหมาย ทว่าเมื่อจู่ๆเขาไม่สามารถยืนยันตัวตนของตนเองได้ ทั้งโทรศัพท์ที่สามารถปลดล็อกด้วยลายนิ้วมือกลับไม่รู้จำ เจ้าของทรัพท์สินทุกอย่างเปลี่ยนไปและเพื่อนเพียงคนเดียวที่คอยช่วยเหลือก็หายตัวไปอย่างไร้ร่องรอย ไม่นานนัก มุนแจ กลับพบว่ามีบุคคลลึกลับกลับถูกเรียกว่าหนู ไม่ได้ขโมยทั้งชื่อ ชีวิต และตัวตนของเขาไปอย่างแนบเนียน ทำให้เขากลายเป็นคนไร้ตัวตนในสายตาของทุกคน เพื่อทวงคืนความยุติธรรมชีวิตของตนเอง เขากลับเริ่มออกตามล่าว่าใครเป็นคนอยู่เบื้องหลังแผนการครั้งนี้ ระหว่างทางทุกอย่างกลับทำให้เขาต้องเข้ามาร่วมมือกับ โนจา เจ้าหนี้นอกระบบผู้เยือกเย็นและอันตราต ซึ่งตามล่าเขามาหลายปีหลังจากมุนแจหายตัวไปพร้อมกับหนี้ก้อนโต ทั้งสองมีเป้าหมายต่างกันอย่างสิ้นเชิง ทั้งสองมีเป้าหมายต่างกัน แต่กลับต้องจับมือกันเพื่อไล่ล่าผู้เป็นต้นเหตุของทุกสิ่ง เมื่อการตัดสินใจสืบสวนดำเนินลึกลงเรื่อยๆ ความจริงที่ถูกซ่อนเอาไว้เริ่มเปิดเผย พร้อมเกมหลอกลวงที่เต็มไปด้วยการหักมุม การทรยศ และการตั้งคำถามว่าแท้จริงแล้ว ตัวตน ของคนเราสามารถถูกช่วงชิงไปได้ง่ายเพียงใด ซีรีส์จะพาผู้ชมติดตามการไล่ล่าทางจิตวิทยาอันเข้มข้น ที่ไม่มีใครไว้ใจใครได้จนถึงวินาทีสุดท้าย  \r\n",
