    "videoUrl": "https://torbo007.com/embed/58cd723c5b2e210f66b62ec4e66e6fd2",
    "sourceType": "embed",
    "description": "เรื่องย่อ: สจ๊วตล่มแผนกู้จักรวาล\r\n บอกเล่าเรื่องราวของ “สจ๊วตบลูม” เจ้าของร้านหนังสือการ์ตูนแห่งหนึ่งของมุมเมืองที่แสนอาภัพ แต่แล้วเขากลับกลายเป็นผู้แบกรับชะตากรรม ของจักรวาลโดยไม่ตั้งใจ จากเหตุการณ์ที่เขาได้ทำอุปกรณ์ทดลองด้านควอนตัมที่เชลดอนและลีโอนาร์ดสร้างขึ้นเสียหาย จนส่งผลให้กำแพงระหว่างโลกคู่ขนานแตกสลาย เกิดหายนะมัลติเวิร์สที่ทำให้ความเป็นจริงบิดเบือน ผู้คนและเหตุการณ์จากจักรวาลต่าง ๆ เริ่มปะปนกันอย่างไร้การควบคุม แม้ว่าทุกอย่างจะไม่ใช่แค่การจำลองวิทยาศาตร์หรือฮีโร่ แต่สจ๊อตก็ไม่มีทางเลือกนอกร่วมมือกับเดนิส, เบิร์ต และ แบร์รี คริปกี เพื่อออกเดินทางข้ามมิติ แก้ไขความผิดพลาด และป้องกันไม่ให้ทุกจักรวาลล่มสลาย ระหว่างทางพวกเขาต้องเผชิญกับเวอร์ชันทางเลือกของตัวละครคุ้นเคยจาก The Big Bang Theory ทั้งในรูปแบบที่คาดไม่ถึงและเต็มไปด้วยอันตราย สำหรับซีรี่ย์เรื่องนี้ต้องบอกเลยว่าไม่ควรพลาดในการรับชมอย่างแน่นอน พร้อมเสิร์ฟความบันเทิงให้แฟนๆได้รับชมกันแล้วตั้งแต่วันนี้เป็นนี้เป็นต้นไป และความสนุกของเรื่องที่มีมาไว้กับ เว็บดูซีรี่ย์ G4 กันแล้วค่าา\r\n",
