    "description": "เรื่องย่อ: เก้าสกุล | 老九门2 \r\n สิ้นสุดการรอคอย กับภาคต่อของซีรี่ย์แนวแอ็กชั่น ผจญภัย ลึกลับ ที่เข้ามาสานต่อเรื่องราวของเหล่าผู้กล้าผู้นำแห่ง เก้าสกุล แห่งยุคสาธารณรัฐจีน เมื่อมีพายุคลื่นลูกใหม่แห่งความวุ่นวานได้เกิดขึ้นแห่งเมืองฉางซานต่างก็ต้องเผชิญหน้ากับปริศนาใหม่ ที่ทุกอย่างชี้ทางไปยังสุสานโบราณ สมบัติลึกลับ และความลับที่ถูกซ่อนไว้มานานนับชั่วอายุคน หลังจากเหตุการณ์ความวุ่นวายจากซีซั่นแรก เหล่าผู้นำเก้าสกุลต้องกลับมาร่วมมือกันอีกครั้ง เมื่อมีเบาะแสของขุมทรัพย์โบราณ และอำนาจลึกลับที่อาจจะเข้ามาเปลี่ยนแปลงโชคชะตาของพื้นที่แห่งนี้ไปได้ เมื่อการออกเดินทางครั้งใหม่กลับเต็มไปด้วยกับดัก ปริศนา และศัรรูที่แข็งแกร่งกว่าเดิม แต่และคนต่างมีเป้าหมาย และความลับของตนเอง ทำให้พันธมิตรที่เคยเหนียวแน่นต้องเผชิญหน้ากับบททดสอบอีกมากมายนับครั้งไม่ถ้วน แต่แล้วท่ามกลางการต่อสู้ เพื่อปกป้องบ้านเมือง และการเปิดโปรงความจริงที่เก็บว่อนตั้งแต่อดีต พร้อมการปรากฎตัวของตัวละครใหม่อีกครั้ง พร้อมการเดินหน้ากับการหักหลัง การเสียสละ และการตัดสินใจที่อาจจะเปลี่ยนแปลงทุกอย่างไปเรื่อยๆ สุดท้านแล้วการเสียสละทุกอย่างจะเป็นการตัดสินใจครั้งสุดท้าย ที่พวกเขาต่างพยายามกันสุดชีวิตเพื่อแลกมา และซีรี่ย์เรื่องนี้จะพาทุกคนไปดำดิ่งสู่โลกแห่งความเป็นจริงทั้งหมด   \r\n",
