    "description": "เรื่องย่อ: ฝ่าบาททรงพระเจริญหมื่นปี | 御庭谣\r\n เรื่องราวการเมืองในราชสำนัก ที่เข้ามาถ่ายทอดพันธมิตรระหว่างราชวงศ์ ทั้งสองอาณาจักรที่ถูกสรรสร้างขึ้นมาใหม่อีกครั้ง พร้อมพันธะสัญญาวิวาห์ เพื่อทวงคืนความยุติธรรมความขัดแย้งที่ยื้ดเยื้อมานานนับปี พร้อมหญิงสาวที่เต็มเปื่ยมด้วยสติปัญญา และความกล้าหาญจำต้องละทิ่งชีวิตที่คุ้นเคย จึงจำยอมต้องเดินทางเข้ามาสู่ราชสำนัก ของแต่ละแค้วนเพื่อเข้าร่วมพิธีอภิเษกกับองค์ชายผู้ได้รับยกย่องในฐานะนักรบผู้เก่งกาจ ในรูปลักษณ์อันเย็นชานั้น กลับไม่มีใครสามารถรับรู้ถึงความเจ็บปวดมาตั้งแต่เยาว์วัย เมื่อการแต่งงานที่ควรเป็นสัญลักษณ์ แห่งความสันติสุขทุกอย่างกลับเต็มไปด้วยความหวาดระแวง ทั้งสองต่างสงสัยว่าอีกฝ่ายอาจเป็นเพียงหมากเกมตัวหนึ่ง ในหมากเกมการเมืองของราชวงศ์ ขณะเดียวกันนั้นเหล่าขุนนางผู้ทรงอำนาจต่างพยายามใช้ความขัดแย้งของทั้งคู่เป็นเครื่องมือในการแย่งชิงชิงอำนาจ ทำให้ชีวิตภายใต้วังหลวงกลับเต็มไปด้วยการหักหลัง การใส่ร้าย และการวางแผนลอบสังอย่างต่อเนื่อง ท่ามกลางเหตุการณ์อันตรายของทั้งสองต่างต้องจำยอมจับมือกัน เพื่อสืบหาความจริงหลังจากเหตุการณ์ปริศนาที่เชื่อมโยงไปถึงความลับของราชวงศ์และผู้บงการตัวจริง ยิ่งทั้งสองต่างร่วมมือกันมากเท่าไหร่ กำแพงที่เคยเกิดขึ้นระหว่างกันค่อยๆ พังทลาย ความไม่ไว้วางใจแรปเปลี่ยนเป็นความเข้าใจ ความเคารพ และก่อเกิดเป็นความรักที่แข็งแกร่งเกินผู้ใดพรากไปได้ แต่อย่างไรก็ตามแม้ว่าเส้นทางแห่งความรักกลับไม่ได้โปรดด้วยกลีบกุหลาบ เมื่อศัตรูแอบซ่อนตัวอยู่ในเงามือเริ่มเคลื่อไหวพร้อมการเปิดฉากโค่นล้มราชบัลลังก์ และจุดเริ่มต้นของสงครามครั้งใหม่ขึ้นมาอีกครั้ง พร้อมการเผชิญหน้ากับบททดสอบครั้งสำคัญ ที่จะตัดสินทั้งชะตาความรักและอนาคตของทั้งสองอาณาจักร สำหรับซีรี่ย์เรื่องนี้ทุกอย่างกับเต็มไปด้วยเรื่องราวความรัก และเกมการเมืองที่เข้มข้นมากขึ้นเรื่อยๆ การสืบหาความจริง และฉากการต่อสู้ที่น่าตื่นเต้น และนี่เองจึงเป็นซีรี่ย์ที่พยายามถ่ายทอดให้คนดูได้เป็นถึงความโรแมนติก และการช่วงชิงอำนาจในราชสำนัก และนี่เองกฝ้เป็นอีกหนึ่งเรื่องที่น่าติดตามชมเป็นอย่างมาก พร้อมชวนให้คนดูได้ลุ้นกับการตัดสินใจ ที่อาจจะเปลี่ยนแปลงโชคชะตาของราชวงศ์ไปตลอดกาล     \r\n",
