    "description": "เรื่องย่อ: ฆาตกรรมสังเวยเลือด\r\n 📝เรื่องราวหลักจากฤดูใบไม้ผลิที่สต็อกโฮล์ม เมื่อที่ถูกแสงอาทิต์สาดส่องมาอย่างยาวนาน จนความมืดแทนจะไม่ได้ย่างกรายเข้ามา แต่แล้วความมืดทุกอย่างกลับเริ่มเข้ามาใกล้มากขึ้นเรื่อยๆ พร้อมทำให้จิตใจของมนุษย์กลับเริ่มขึ้น เมื่อเกิดเหตุแจ้งความคดีบุกรุกบ้านพักตากอากาศบนแห่งร้างแห่งหนึ่ง แต่แล้วเจ้าหน้าที่ตำรวจสองนายถูกส่งตัวเข้ามาสืบหาความจริงอีกครั้ง แต่แล้วกลับเพียงหลักฐานอันว่างเปล่า ทว่าความรุ่งขึ้น ทั้งสองกลับกลายเป็นศพที่ถูกฆาตกรรมอย่างโหดรเหี้ยม แต่แล้วเหตุการณ์เหล่านี้กลับเป็นเพียงจุดเริ่มต้นของคดีฆาตกรรมต่อเนื่องสุดสยาง ที่พุ่งเป้าชี้ทางไปยังเจ้าหน้าที่ตำรวจโดยเฉพาะ พร้อมทำให้ โทมัส เบิร์ก นายตำรวจฝีมือดีเขากลับตกเข้ามาอยุ่ในภาวะกดดันและจนปัญญา พร้อมการตัดสินใจเดิมพันครั้งสำคัญด้วยการบากหน้าไปขอความช่วยเหลือจาก อัลเฟรด อดีตเจ้าหน้าที่ตำรวจสายสืบสูงวัยผู้ขวางโลก ซึ่งเป็นพ่อแม่แท้ๆ ที่ห่างเหินและไม่ลงรอยกันมาโดยตลอด สุดท้ายแล้วซีรี่ย์เรื่องจะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ\r\n\r\n",
