    "description": "เรื่องย่อ: ท่านประธานกำมะลอ | 아파트 \r\n  “เรื่องราวเหลือเชื่อของหนุ่มธรรมดาที่พยายามไตร่เต้าขึ้นมาเป็นประธานใหญ่ผู้ทรงเกียรติ” พัคแฮกัง ที่เป็นหันหน้าแก๊งอันธพาล ที่ใช้ชีวิตอย่างในโลกสีเทาและกานทวงหนี้ปวันๆ จากอำนาจในพื้นที่ที่ไม่มีใครสามารถกล้าต่อกร แต่เมื่อมีชายหนุ่มที่เปรียบเสมือนพ่อของเขาที่กำลังตกอยู่กับสถานการณ์คับขัน และต้องใช้เงินก้อนมหาศาล พัคแฮกัง จึงเข้ามาวางแผยครั้งใหญ่ด้วยการสมัครรับเลือกตั้งเป็น (ประธานฝ่ายนิติบุคคล) ของตึกสูงแห่งหนึ่ง โดยมีเป้าหมายลับคือการการเข้าถึงเงินกองทุนซ่อมบำรุงมูลค่ามหาศาล ที่ถูกซ่อนอยู่กับโครงการที่กำลังสร้างขึ้น อย่างไรก็ตามการวางแผนเพื่อปล้นเงินกองนี้กลับทำให้เขาต้องค้นพบกับการเชื่อมโยงเครือข่ายของการ (คอร์รัปชัน) การทุจริต ของเหล่าผู้มีอิทธิพลที่แสวงหาแต่ผลประโยนช์ เพราะเหตุนี้เองกลับทำให้เขาต้องเข้ามาร่วมมือกับ คังฮาริ หญิงสาวผู้ใฝ่ฝันอยากเป็นทนายความ และเหล่าเพื่อนบ้าน เพื่อการเปิดโปรงเบื้องหลังการช่อโกงกินฝังรากฐานลึกในอพาร์เมนต์แห่งนี้ พร้อมการเผชิญหน้ากับทนายความสาวผู้มีเป้าหมายครอบครองเงินกองทุนก้อนเดียวกัน จากชีวิตของชายหนุ่มที่หวังเพียงแค่การหาเงินก้อนโต แต่ต้องกลับกลายเป็นฮีโร่ที่เข้ามาปกป้องบ้าน เพื่อการหลบหลีกต่อผู้มีอำนาจ และการหักเหลี่ยมเฉือนคมที่ได้เกิดขึ้นในครั้งนี้  แต่แล้วท่ามกลางการเมืองที่ติดอยู่ภายใตอพาร์เมนต์ ซึ่งเป็นการเปลี่ยนแปลงจากสนามเล็กๆ สู่การผันตัวเป็นของการเดิมพันในครั้งนี้\r\n",
