    "videoUrl": "https://torbo007.com/embed/e616a15c0911d63fee00435563dbcb4e",
    "sourceType": "embed",
    "description": "เรื่องย่อ: แฟนสาวอัจฉริยะ | 天才，女友\r\n เรื่องราวความรักของชายหนุ่มธรรมดาๆที่ใช้ชีวิตเต็มไปด้วยความผิดหวัง แต่แล้ววันหนึ่งกลับมีหญิงสาวอัจฉริยะผู้มีไอคิวเหนือคนทั่วไปอย่าง หลินจือเซี่ย ทั้งความสามารถที่เก่ง ฉลาด และประสบความสำเร็จในทุกด้าน แต่กลับไม่เข้าใจความรู้สึกและความสัมพันธ์ของผู้คนที่คู่ควร เพราะใช้ชีวิตอยู่กับเหตุผลมากกว่าอารมณ์ แม้ว่าทั้งคู่จะมาจากโลกที่แตกต่างกันกันสุดขั้ว แต่โชคชะตากลับนำพาให้พวกได้กลับมาใกล้ชิดกันมากขึ้น จากความไม่ลงรอยในช่วงแรกค่อยๆ พัฒนาเป็นความผูกพันและความรัก ขณะเดียวกันนั้นทั้งสองต่างต้องร่วมมือกันฝ่าฟันอุปสรรคจากหน้าที่การงาน ความคาดหวังหวังของครอบครัว และการแข่งขันในสังคมที่กดดันมานานแสนนาน แต่แล้ว หูอี้เทียน ที่พยายามผลักดันให้เธอเรียนรู้ถึงคุณค่าของความรัก ความอบอุ่น และการใช้ชีวิตด้วยหัวใจ ส่วน หลินจื้อเซี่ย กลับใช้ความสามารถอันโดดเด่นช่วยผลักดันให้เขาเติบโตและกล้าออกทำตามความฝันมากขึ้น ทั้งสองจึงค่อยๆ เข้ามาเติมเต็มสิ่งที่ขาดหายไปของอีกฝ่าย สำหรับซีรี่ย์เรื่องนี้ก็เป้นอีกหนึ่งเรื่องที่ชักชวนให้น่าหลงใหล พร้อมการบอกเล่าเรื่องราวความนักที่ไม่ได้มาจากความสมบูรณ์แบบ แต่เกิดจากการเรียนรู้จากความสัมพันธ์ การยอมรับความแตกต่าง พร้อมที่ร่วมจับมือกันก้าวผ่านเรื่องราวร้ายๆเหล่านี้ จนทุกอย่างนำทางมาสู่เรื่องราวความอบอุ่นหัวใจอีกครั้ง แต่แล้วจุดจบของเรื่องราวทั้งหมดจะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ   \r\n",
