    "description": "เรื่องย่อ: มือใหม่หักแค้น | 신입사원 강회장 \r\n “จากการสลับร่างและวิญญาณของประธานรุ่นใหญ่ และหนุ่มนักกีฬาต้องมาพบเจอกับปัญหาความวุ่นวายในช่วงเวลานี้” บอกเล่าเรื่องราวของ “คังยงโฮ” ประธานรุ่นใหญ่ที่ใกล้เกษียณ และมีความเก่งระดับประเทศ หรือใครหลายๆคนต่างรู้จักเขาจากชื่อ “เทพเจ้าแห่งธุรกิจ” ที่บังเอิญได้รับอุบัติเหตุขึ้นมาอย่างกระทันหัน ในความบังเอิญเหล่านั้นกลับทำให้เขาต้องสลับร่งกับ “ฮวังจุนฮยอน” หนุ่มนักฟุตบอลชาย ที่มีอนาคต พร้อมการเตรียมตัวแข่งขันทีมในเครือ เมื่อประธานใหญ่ที่ติกอยู่ในร่างของเด็กหนุ่ม กลับพยายามเริ่มต้นชีวิตใหม่อีกครั้ง ในการเข้ามาเป็นพนักงานใหม่ พร้อมการรับมอบหมายในการรับภารกิจอันน่ากลัว พร้อมการแข่งขันที่ทุกอย่างเต็มไปด้วยกลโกง และเล่ห์การแข่งขันที่เริ่มต้นสูงมากขึ้นเรื่อยๆ จากชายวัยชรา ที่ต้องออกมาใช้ชีวิตอย่างวัยรุ่นอีกครั้ง และการใช้ความรู้ที่มีงัดออกมาใช้ปกป้องตนเองและความแข่งแกร่งในการเริ่มต้นเป็นนักกีฬา  \r\n",
