    "titleTh": "Love Has Fireworks เมื่อรักส่องประกาย (2026) ซับไทย/พากย์ไทย EP.1-36",
    "titleEn": "Love Has Fireworks เมื่อรักส่องประกาย (2026) ซับไทย/พากย์ไทย EP.1-36",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/06/99-4.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/06/99-4.jpg",
    "videoUrl": "https://torbo007.com/embed/7866207943f14d0f33d4a216cd0e41f2",
    "sourceType": "embed",
    "description": "เรื่องย่อ: เมื่อรักส่องประกาย | 爱情有烟火\r\n Love Has Fireworks เมื่อรักส่องประกาย (2026) ซีรี่ย์โรแมนติกอบอุ่นหัวใจ ที่บอกเล่าเรื่องราวของชายหญิงสองคนซึ่งต่างผิดหวังจากความรักและต้องเผชิญมรสุมชีวิต เมื่อโชคชะตานำพาให้พวกเขามาอยู่ร่วมชายคาเดียวกัน ความสัมพันธ์ที่เริ่มต้นจากความบังเอิญค่อย ๆ เปลี่ยนเป็นความผูกพัน และจุดประกายความรักครั้งใหม่ที่สวยงามราวกับดอกไม้ไฟที่ส่องสว่างกลางคืนอันมืดมิด บอกเล่าเรื่องราวของ เฉียนเฟย พนักงานธนาคารสาวที่พยายามวางแผนร่วมกับคู่หมั้นอย่างมีความสุข แต่สุดท้ายแล้วทุกอย่างกลับเริ่มพลิกผันมากยิ่งขึ้น เพียงเพราะเธอถูกทิ้งให้เริ่มต้นชีวิตใหม่อีกครั้ง ในขณะเดียวกันนั้น หลี่อี้เฟย ชายหนุ่มผู้แสนเย็นชาจากตระร่ำรวย เมื่อเขาพยายามทุ่มเทชีวิตให้กับงานมากกว่าความรักเลยก็ว่าได้ แต่แล้วเขากลับบอกเลิกแฟนสาวด้วยความสิ้นหวังในช่วงเวลาที่ยากลำบากอีกครั้ง แต่แล้วภาระที่หนักแน่น ด้วยภาระค่าผ่อนบ้าน เฉียนเฟยจึงตัดสินใจปล่อยห้องเช่า และโชคชะตาก็นำพาให้หลี่อี้เฟยเข้ามาเป็นผู้เช่าคนใหม่ ทั้งคู่ที่มีมุมมองชีวิตและความรักแตกต่างกันสุดขั้ว ต้องใช้ชีวิตร่วมชายคาเดียวกัน เกิดทั้งความขัดแย้ง ความวุ่นวาย และเรื่องราวชวนอบอุ่นหัวใจมากมา ท่ามกลางปัญหาจากหน้าที่การงาน และปัญหาที่ผ่านเข้ามาในชีวิต ความสัมพันธ์ของคนทั้งสองที่ค่อยๆ พัฒนาจากคนแปลกหน้าสู่คนสำคัญ จนกลายเป็นความรักที่พร้อมเข้ามาเยียวยาจิตใจของคนทั้งสองคนนี้ \r\n",
