    "description": "เรื่องย่อ:คู่คนชนเดือด\r\n เรื่องราวเริ่มต้นเมื่อสองนักสู้ต่างขั้วต้องเผชิญหน้ากันกลางสนามประลองที่เต็มไปด้วยความแค้น ฝ่ายหนึ่งคืออดีตนักมวยผู้สูญเสียทุกอย่างจากการทรยศของคนใกล้ตัว อีกฝ่ายคือชายหนุ่มหัวร้อนที่เติบโตมากับชีวิตข้างถนนและไม่ยอมแพ้ต่อโชคชะตา การปะทะกันของทั้งคู่ไม่ได้มีเพียงชัยชนะเป็นเดิมพัน แต่ยังรวมถึงศักดิ์ศรีและความอยู่รอด ระหว่างทางพวกเขาต้องเผชิญกับแก๊งอิทธิพลและศัตรูที่พร้อมทำทุกวิถีทางเพื่อกำจัดทั้งสอง จากคู่ต่อสู้ที่พร้อมฆ่ากัน ทั้งคู่เริ่มมองเห็นบาดแผลในใจของกันและกัน ความสัมพันธ์ที่เต็มไปด้วยความขัดแย้งค่อย ๆ กลายเป็นความเชื่อใจท่ามกลางอันตราย แต่เมื่อความจริงเกี่ยวกับอดีตถูกเปิดเผย ความแค้นครั้งใหม่ก็ปะทุขึ้นอย่างรุนแรง ศึกสุดท้ายจึงกลายเป็นการต่อสู้ที่เดิมพันด้วยชีวิตและอนาคตของทุกคน “คู่คนชนเดือด” คือเรื่องราวแอ็กชันดราม่าที่สะท้อนมิตรภาพ ความแค้น และการต่อสู้เพื่อศักดิ์ศรีจนถึงลมหายใจ\r\n",
