    "titleEn": "Bridgerton Season 4 บริดเจอร์ตัน: วังวนรัก เกมไฮโซ 4 (2026) พากย์ไทย EP.1-8",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/01/99-6.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/01/99-6.jpg",
    "videoUrl": "https://torbo007.com/embed/13d36d0fd20caf4c9745321d23f97ecd",
    "sourceType": "embed",
    "description": "เรื่องย่อ บริดเจอร์ตัน: วังวนรัก เกมไฮโซ 4| รักแท้ภายใต้หน้ากาก\r\n  “จากชายหนุ่มบ้านรวยที่ต้องตกหลุมรักหญิงสาวบ้านนาอีกครั้ง” บอกเล่าเรื่องราวของชายหนุ่มผู้ไม่เอาไหน ด้วยคำขอสุดท้ายของผู้เป็นแม่ เพียงแค่จะขอให้ลูกชายต้องมาเข้าร่วมงานเต้นรำสวมหน้ากากในค่ำคืนนี้ ด้วยความฝื้นใจและไม่จำใจจะมาในงานนี้ และได้ทำให้เขาได้ต้องมาพบกับหญิงสาวคนหนึ่งในชุดราตีที่โดดเด่นมากในงาน และยังคงเป็นที่ต้องมาต้องใจของใครหลายๆคน ในค่ำคืนอันแสนหวานกลับต้องจบลงอย่างรวดเร็ว และนี่เองทุกอย่างกลับเป็นจุดสนใจและพยายามให้เขาออกจามหาเธออยู่เรื่อยมา แต่ด้วยความบังเอิญกลับทำให้เขาและเธอได้เจอกันอีกครั้ง และเขาก็ต้องพบว่าหญิงสาวเป็นเพียงสาวใช้ธรรมดาๆคนหนึ่งที่ผมีฐานะต่างจากเขาตนละชั้น ด้วยความใกล้ชิดทุกอย่างกลับกลายเป็นความรักหรือไม่ แต่แล้วความรักของทั้งสองจะลงเอยอย่างไรเราไปรับชมพร้อมกันค่ะ🕊️☄️ สำหรับซีรี่ย์เรื่องนี้ก็สามารถรับชมพร้อมกันได้แล้วในวันที่ 29 มกราคม 2569 และสามารถรับชมภาคสองได้ในวันที่ 26 กุมภาพันธ์ 2569 สานต่อความสนุกและความเข้มข้นไปพร้อมกันกับเราได้แล้วที่ G4 แหล่งรวมซีรี่ย์ ครบ จบ ในที่เดียว\r\n",
