    "titleTh": "Radioactive Emergency มหันตภัยกัมมันตภาพรังสี (2026) พากย์ไทย EP.1-5",
    "titleEn": "Radioactive Emergency มหันตภัยกัมมันตภาพรังสี (2026) พากย์ไทย EP.1-5",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/03/555555.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/03/555555.jpg",
    "videoUrl": "https://torbo007.com/embed/963bcf142dbc99ab09715ff4ed4a8937",
    "sourceType": "embed",
    "description": "เรื่องย่อ:-มหันตภัยกัมมันตภาพรังสี\r\nเรื่องราวเปิดมาที่  “ฮัน จีอู” วิศวกรหนุ่มผู้ดูแลระบบความปลอดภัยเริ่มสังเกตว่าค่ากัมมันตภาพรังสีพุ่งสูงอย่างผิดปกติ แต่คำเตือนของเขากลับถูกมองว่าเป็นเพียงความผิดพลาดของระบไม่นานหลังจากนั้น การรั่วไหลของกัมมันตภาพรังสีก็เริ่มลุกลามออกจากเขตควบคุม เมืองทั้งเมืองต้องเผชิญกับความตื่นตระหนก ผู้คนพยายามอพยพหนีเอาชีวิตรอดท่ามกลางความโกลาหล ในขณะที่รัฐบาลพยายามปกปิดความจริงเพื่อไม่ให้เกิดความแตกตื่น “คัง ซอริน” นักข่าวสาวกลับเริ่มสืบหาความจริงเบื้องหลังอุบัติเหตุครั้งนี้ ยิ่งเธอสืบลึกลงไปมากเท่าไร ก็ยิ่งพบเงื่อนงำที่ชวนให้สงสัยว่าเหตุการณ์ทั้งหมดอาจไม่ได้เกิดจากอุบัติเหตุธรรมดา ขณะเดียวกันทีมกู้ภัยฉุกเฉินต้องเสี่ยงชีวิตเข้าไปในพื้นที่ปนเปื้อน เพื่อช่วยเหลือผู้คนที่ยังติดอยู่ภายในเขตอันตราย เวลาทุกนาทีมีค่า เพราะระดับรังสีกำลังเพิ่มขึ้นอย่างต่อเนื่อง และความผิดพลาดเพียงครั้งเดียวอาจทำให้ภัยพิบัติครั้งนี้ลุกลามจนควบคุมไม่ได้ ท่ามกลางสถานการณ์ที่บีบคั้น ผู้คนต่างต้องตัดสินใจเลือกระหว่างหน้าที่ ความจริง และการเอาชีวิตรอด ความลับที่ถูกปิดซ่อนมานานกำลังจะถูกเปิดเผย พร้อมกับคำถามสำคัญว่า ใครกันแน่ที่ต้องรับผิดชอบต่อมหันตภัยครั้งนี้",
