    "description": "เรื่องย่อ-สติงเกอร์ส: หน่วยลับจับวายร้าย\r\n เรื่องราวเปิดมาที่ นิไคโด ทามิโกะ เจ้าหน้าที่สายสืบพิเศษ เมื่อเธอได้รับหน้าที่ให้ถูกส่งตัวเข้ามาสืบหาความจริงเกี่ยวกับเหล่าผู้ก่อการร้ายที่กำลังก่อความวุ่นวายมากในตอนนี้ เพราะเหตุผลเหล่านี้จึงทำให้เธอปลิมตัวเจ้ามาอยู่ในจุดเสี่ยงอันตรายมากยิ่งขึ้น แต่แล้วเธอก็ได้เลื่อนขึ้นให้เป็นหัวหน้าทีมหน่วยสืบสวนพร้อมที่จะปราบปรามเหตการณืที่กำลังเกิดขึ้นมาในตอนนี้ พร้อมการนำทุกอย่างเข้ามาสู่่ความท้าทายกับเหล่าผู้พิทักษ์ต่อกฎหมายอีกครั้ง แต่สุดท้ายแล้วบทสรุปของเรื่องราวทั้งหมดจะจบลงอย่างไรเราไปรับชมพร้อมๆกันค่ะ\r\n",
