    "sourceType": "embed",
    "description": "เรื่องย่อ-โอบรักแรงเสน่หา | 炽热吸引\r\n  บอกเล่าเรื่องราวที่เกี่ยวกับความรักโดยคนทั่วไปเรียกว่าความรักผิดประเภท จากเด็กสาวผู้แสนธรรมดาๆคนหนึ่ง อู๋หนงอวี่ ที่ได้รู้จักกับชายหนุ่มปริศนาคนหนึ่งที่ได้ก้าวขาเข้ามาในชีวิเธอ จากร่างกายที่ต่อต้านสังคม และคนรอบข้างที่ดูเหมือนว่าเขาจะไม่เอาไหนเลยแม้แต่นิดเดียว ด้วยความใกล้ชิดของทั้งสองต้องถูกโยงเข้ามาสู่ความเจ็บปวดและความวุ่นวายที่กำลังจะเริ่มต้นขึ้นมาใหม่ ห้าปีต่อมา อู๋หนงอวี่ ที่ได้เติบโตเป็นนักศึกษดา ด้านพันธุกรรมส่วนชายหนุ่มก็กลับกลายบุคคลที่เย็นชา และไม่เอาไหนอีกครั้ง ด้วยความบังเอิญจึงทำให้คนทั้งสองได้มาพบกันอีกครั้งหรือว่าทุกอย่างจะไม่แรงดึงดูดของทั้งสอง แต่แล้วเรื่องราวความรักของคู่นี้จะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ สไหรับซีรี่ย์เรื่องนี้ก็ได้ออกอากาศไปแล้วตั้งแต่วันที่ 22 มกราคม 2026 จำนวน 30 ตอนเพียงเท่านั้น มาพร้อมมาในรูปแบบซับไทย ให้แฟนๆได้รับชมไปพร้อมกันๆกับเราแล้ว   \r\n",
