    "titleTh": "We Almost Broke Up รักนี้รีเพลย์ไม่เลิก (2025) พากย์ไทย EP.1-14",
    "titleEn": "We Almost Broke Up รักนี้รีเพลย์ไม่เลิก (2025) พากย์ไทย EP.1-14",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/02/9-13.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/02/9-13.jpg",
    "videoUrl": "https://torbo007.com/embed/a6c54472a956bd3fff4374eedbd2e4f6",
    "sourceType": "embed",
    "description": "เรื่องย่อ: รักนี้รีเพลย์ไม่เลิก\r\n บอกเล่าเรื่องราวของคู่ข่าวสาวคู่หนึ่งเมื่อพวกเขาทั้งสองได้ตัดสินใจเลิกรากันไปเพียงเพราะความไม่เข้าใจซึ้งกันและกัน แต่ในค่ะคืนเดียวกันนั้น เสิ่นเมิ่ง ได้ประสบอุบัตเหตุรุนแรงและทำให้เขากลับกลายเป็นบุคคลต้องสงสัยในคดีครั้งนี้ วันต่อมาเขากลับได้มาพบว่ากำลังนอนอยู่บนเตียงเดิม และทั้งสองต่อก็พร้อมที่จะเข้ามาลงทุนทำหนังสั้นคริปหวานชื่นให้กับ และดูเหมือนว่าทุกอย่างกำลังเป็นเรื่องราวสมบูรณ์แบบมากที่สุด ด้วความรักที่กำลังผลบานทุกอย่างกับเรื่องคลุมเครือเพียงมีทนายเข้ามาวุ่นวายในชีวิตของพวกเขามากยิ่งขึ้น และกลับคือผู้ถูกเลือกให้ผิดหวัง พร้อมกับการทำภารกิจโปรเจกชิ้นนี้ออกมาให้สำเร็จในครั้งนี้ เมื่อความสัมพันธ์ที่ซับซ้อนทุกอย่างจะสามารถเปลี่ยนแปลงได้หรือไม่เราไปรับชมพร้อมๆกันค่ะ หากเพื่อนๆคนไหนที่กำลังมองหาซีรี่ย์เรื่องใหม่เอาไว้รับชมก็ไม่ควรพลาดกับ G4 แหล่งรวมซีรี่ย์เรื่องที่เรามีมากกว่าสามพันเรื่อง และเรียกได้ว่าครบ จบ ในที่เดียวเลยจริงๆ     \r\n",
