    "sourceType": "embed",
    "description": "พล็อตเรื่อง คุโจยอดทยานบาป | 九条の大罪\r\n เมื่อทนายหนุ่มสุดมั่นต้องมาพบเจอกับควงามxิปหายอีกครั้ง” บอกเล่าเรื่องราวของทนายหนุ่ม ผู้ที่ถูกคนอื่นๆลือว่าเขาเป็นบุคคลที่ไม่เคยแพ้ต่อความการว่าความแก้แต่ครั้งเดี่ยว จนกระทั่งเขาต้องมาพบกันอีกครั้งนี้ แต่เมื่อเขาได้มาพบกับลูกความคนสำคัญอีกครั้ง แต่หากรู้หรือไม่ว่าชายหนุ่มคนนั้นกับเป็นคนร้ายที่ก็ได้ก่อความชั่วเอาไว้มากนักต่อนัก และในครั้งนี้เองเขากลับเชื่ออย่างเต็มที่เลยว่าเขาจะชนะในคดีความครั้งนี้ แต่หากรู้หรือไม่ว่าทุกอย่างจะต้องจบลงไปอย่างความบังเอิญ แต่แล้วเมื่อความยุติธรรมของ ทนายหนุ่มที่ต้อเลือกระหว่างการปกป้องลูกความหรือความยุติธรรมที่ตนเองได้ตั้งมั่นเอาไว้มาตั้งแต่แรก  \r\n",
