    "sourceType": "embed",
    "description": "เรื่องย่อ-สองฟากของความจริง\r\n  เมื่อเรื่องราวความวุ่นวายของเมืองแห่งหนึ่ง ที่มีแต่ความสงบสุขขนกระทั่งเกิดเรื่องราวความชิปหายขึ้นมาอีกครั้งเมื่อพวกเขาได้มาพบกับคดีปริศนาเรื่องหนึ่ง แต่กับมีครอบครัวๆหนึ่งที่คู่สามีและภรรยาตำรวจและนักข่าวสาวที่ได้ตัดสินใจแยกทางกันเพียงเพราะความเข้าใจที่ไม่ตรงกัน และทั้งสองจึงได้มาพบกันอีกครั้งในการสืบหาคดีที่สำคัญเหล่านี้ ต่างก็แย่งชิงกันเพียงเพราะที่จะรีบปิดคดีปริศนาเหล่านี้ ทว่าเรื่องราวความวุ่นวายเหล่านี้ที่ทำให้ทั้งสองต่างก็กลับมาสงสัยฝ่ายตรงข้ามอีกครั้ง แต่เมื่อทุกอย่างกลับมองไม่เห็นทางออกเห็นแม้แต่น้อย แต่แล้วเมื่อพวกเขาทั้งสองร่วมมือกันร่วมกันแก้ไขปริศนาที่ยังค้างคาใจไปได้หรือไม่เราไปรับชมพร้อมๆกันค่ะ สำหรับซีรี่ย์เรื่องนี้ก็เตรยมออกฉายครั้งแรกบนช่องทาง Netflix และสามารถรับชมพร้อมกันได้ในวันที่ 8 มกราคม 2026 ทั้งหมด 6 ตอนที่สามารถรับชมได้แบบรวดเดียวจบ ถ้าหากเพื่อนๆคนไหนที่กำลังมองหาซีรี่ย์เรื่องใหม่เอาได้รับชมก็ไม่ควรพลาดกับ G4 แหล่งรวมความสุขที่ถูกคัดสรรมาไว้ตรงนี้แล้ว!! \r\n",
