    "sourceType": "embed",
    "description": "เรื่องย่อ: สไปเดอร์-นัวร์: ไอ้แมงมุมพันธุ์นรก\r\n Spider-Noir เป็นอีกหนึ่งภาคต่อของเจ้าแมงมุมพันธุ์นรก ที่พร้อมการบอกเล่าเรื่องราวของ “เบน ไรลีย์” นักสืบเอกชนหนุ่มที่มีชีวิตอันวุ่ยวายในยามค่ำคืน จากหน้าที่การงานที่ตกอับในช่วงเวลานี้ ท่ามกลางเมืองใหญ่และความวุ่นวายแห่งปี 1930s “เบน ไรลีย์”เขาต้องเผชิยหน้ากับเรื่องราวอันเจ็บปวด จากโศกนาฏกรรมส่วนตัว พร้อมภาระหน้าที่ในการเป็นซูปเปอร์ฮีโร่ช่วยชาวโลก ภายใต้ท่ามกลางวิกฤตที่กำลังตกต่ำมากในช่วงเวลาเหล่านี้ สำหรับวีรี่ยืเรื่องนี้ต้องบอกเลยว่า ไม่ควรพลาดในการรับชมอย่างแน่นอน ทั้งการเล่าเรื่อง การแสดง โทนเรื่องสไตร์นัวร์ๆที่เข้าถึงอารมณืคนดูได้เป็นอย่างดี ไม่ว่าจะเป็นภาพขาวดำสุดคลาสสิก ที่เข้าถึงความรู้สึกและความลึกลับของตัวซีรี่ย์ได้เป็นอย่างได้ จากความสนุกของเรื่องที่ G4 ได้นำมาเสิร์ฟให้แฟนๆได้รับชมกันแล้วในวันนี้เท่านั้น!!     ",
