    "description": "เรื่องย่อ-In Your Radiant Season | 찬란한 너의 계절에\r\n เรื่องราวเริ่มจาก ซอนอูชาน ชายหนุ่มนักออกแบบแอนิเมชั่นที่มีบุคลิกสดใสและอบอุ่น เหมือนแสงแดดในฤดูร้อน แต่ลึก ๆ เขาซ่อนบาดแผลจากเหตุการณ์ในอดีตไว้เสมอขณะที่ ซงฮารัน หญิงสาวหัวหน้าดีไซเนอร์แห่ง Nana Atelier เป็นคนเคร่งขรึมและปิดกั้นตัวเอง เหมือนฤดูหนาวที่เยือกเย็น เพราะเรื่องราวในอดีตทำให้เธอไม่อยากเปิดใจให้ใคร ทั้งคู่กลับมาเจอกันอีกครั้งหลังจากผ่านไปหลายปี ในจังหวะเวลาที่ต่างฝ่ายต่างกำลังต่อสู้กับความทรงจำและความรู้สึกของตัวเอง การได้ร่วมงานกันทำให้ชานค่อย ๆ เข้าไปในโลกที่ฮารันตั้งกำแพงเอาไว้สูง และเริ่มเห็นด้านที่อบอุ่นและเปราะบางของเธอ\r\nฮารันเองก็เริ่มรู้สึกว่าเส้นแบ่งระหว่างหน้าที่และหัวใจค่อย ๆ เลือนหาย เมื่อเธอได้เห็นความจริงใจของชาน ความทรงจำเก่า ๆ ที่ทั้งคู่เคยมีร่วมกันเริ่มผุดขึ้น ทำให้ทั้งคู่ต้องเผชิญหน้ากับความจริงบางอย่างที่แต่ละคนพยายามหลบเลี่ยง เรื่องราวไม่ได้มีเพียงความรักของคนวัยทำงานเท่านั้น ยังมีเส้นเรื่องของควารักแบบสดใสของวัยรุ่น และเส้นเรื่องราวความรักของคนทั้งสองจะเป็นอย่างไร เราไปรับชมพร้อมๆกันค่ะ\r\n",
