    "videoUrl": "https://torbo007.com/embed/5371bc64e4e0e6a5bae86aa2a7d14670",
    "sourceType": "embed",
    "description": "เรื่องย่อ: ดาวประกายพร่างพรายฝัน | 灿如繁星\r\n เรื่องราวเริ่มต้นเมื่อ หลินหว่านซิง นักจิตวิทยาสาวผู้สำเร็จการศึกษาระดับปริญญาเอก ต้องกลับมายังบ้านเกิดหลังเผชิญกับช่วงเวลาที่ยากลำบากในชีวิต เธอรับตำแหน่งครูในโรงเรียนแห่งหนึ่งของเมืองหงจิ่ง และได้รับมอบหมายให้ดูแลห้องเรียนที่เต็มไปด้วยนักเรียนซึ่งถูกมองว่าเป็น เด็กท้ายแถว ที่ขาดแรงบันดาลใจและไร้เป้าหมายในชีวิต ระหว่างการทำงาน เธอได้พบกับ หวังฝ่า โค้ชฝีมือระดับแนวหน้าผู้ทุ่มเทให้กับการฝึกนักกีฬาเยาวชน แม้ทั้งคู่จะมีแนวคิดในการสอนที่แตกต่างกัน แต่ต่างก็มีเป้าหมายเดียวกัน คือการช่วยให้เด็ก ๆ ค้นพบคุณค่าในตัวเอง และกล้าที่จะไล่ตามความฝัน หลินหว่านซิงเลือกใช้แนวทางการสอนที่เปิดกว้าง ให้นักเรียนได้เรียนรู้จากประสบการณ์จริง ฝึกคิดอย่างอิสระ และค้นหาความสามารถที่แท้จริงของตนเอง ขณะที่หวังฝ่าคอยผลักดันให้พวกเขาเรียนรู้ถึงความมุ่งมั่น ความมีวินัย และการไม่ยอมแพ้ต่ออุปสรรค เมื่อเวลาผ่านไป นักเรียนแต่ละคนค่อย ๆ เปลี่ยนแปลงจากเด็กที่หมดหวัง กลายเป็นคนที่กล้าฝัน กล้าลงมือทำ และพร้อมเผชิญความท้าทายในอนาคต ขณะเดียวกัน ความสัมพันธ์ระหว่างหลินหว่านซิงและหวังฝ่าก็ค่อย ๆ พัฒนาเป็นความรักที่เติบโตจากความเข้าใจและการร่วมฝ่าฟันอุปสรรคไปด้วยกัน\r\n",
