    "titleTh": "Never-Ending Summer ฤดูร้อนนิรันดร์ (2026) พากย์ไทย/ซับไทย EP.1-29",
    "titleEn": "Never-Ending Summer ฤดูร้อนนิรันดร์ (2026) พากย์ไทย/ซับไทย EP.1-29",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/06/9-8.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/06/9-8.jpg",
    "videoUrl": "https://torbo007.com/embed/a4daebf69d936385a29427c50e17c809",
    "sourceType": "embed",
    "description": "เรื่องย่อ: ฤดูร้อนนิรันดร์ | 炽夏\r\n เมื่อความรักอันยาวนานของหนุ่มสาวคู่หนึ่งซึ่งเริ่มต้นขึ้นในช่วงฤดูร้อนหลังเรียนจบ ก่อนจะต้องแยกจากกันเพราะความเข้าใจผิดและปัญหาชีวิตที่ถาโถมเข้ามา บอกเล่าเรื่องราวของ โจวหว่าน จากเด็กสาวธรรมดาๆคนหนึ่ง ต้องเผชิยหน้ากับปัญหาครอบครัว แต่แล้วเมื่อย่าของเธอกำลังป่วยหนัก และต้องใช้เงินในจำนวนมากเพื่อการรักษาอาการป่วยในครั้งนี้ โจวหว่าน จึงยอมเข้ามาขอความช่วยเหลือกับ ลู่ซีเสี่ยว ลูกเลี้ยงเพียงที่ถูกเก็บซ่อนของแม่เธอ เมื่อทั้งคู่เริ่มวางแผนสานต่อความสัมพันธ์แรกเริ่มอย่างไม่ราบรื่น ทว่าเมื่อทั้งสองได้เข้ามาใช้ชีวิตด้วยกันอย่างใกล้ชิดมากขึ้นเรื่อยๆ ในช่วงฤดูจบการศึกษา กลับทำให้ความใกล้ชิดค่อยๆเปลี่ยนแปลงเป็นความรักเล็กๆเริ่มต้นขึ้น อย่างไรก็ตามความรักของคนทั้งสองกลับถูกทำลายด้วยความเข้าใจผิด และแรงกดดันจากความจริง ทำให้ทั้งสองต่างต้องเดินทางแยกจากกันไปนานนับ 10 ปี ดูเหมือนว่าดชคชะตาได้เห็นของพวกเขาทั้งสองจึงทำให้ได้กลับมาพบกันอีกครั้ง แม้ว่า ลู่ซีเสี่ยว ที่เก็บซ่อนความในใจมาโดยตลอด ด้วยอดีตที่มีต่อ โจวหว่าน ที่ไม่เคยจางหายจากความทรงจำเขามาโดยตลอด เมื่อทั้งสองได้เข้ามาร่วมมือกันสืบหาความจริงเบื้องหลังเหตุการณ์ (อุบัติเหตุในโรงงาน) ที่ได้เกิดการเปลี่ยนแปลงของใครหลายๆคน ความลับในอดีตค่อยๆถูกเปิดเผย พร้อมกับโอกาสครั้งใหม่ของความรักที่เคยสูญหายไป สุดท้ายแล้วเรื่องราวของคนทั้งสองคนนี้จะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ \r\n",
