    "sourceType": "embed",
    "description": "เรื่องย่อ: คลื่นสีคราม | 아주르 스프링\r\nที่เล่าเรื่องของ “ซออันนา” อดีตนักกีฬาว่ายน้ำดาวรุ่งที่ต้องสูญเสียความฝันจากอาการบาดเจ็บ จนเธอตัดสินใจกลับมายังเมืองชายทะเลบ้านเกิดของแม่ เพื่อเริ่มต้นชีวิตใหม่อีกครั้ง ที่นั่นเธอได้พบกับ “ยุนด็อกฮยอน” ชายหนุ่มผู้จมอยู่กับอดีตและใช้ชีวิตอย่างเงียบงันในฐานะนักดำน้ำทะเลพื้นบ้าน เมื่อทั้งสองได้เรียนรู้การเป็นแฮนยอและแฮนัม หรือเหล่านักดำน้ำเก็บอาหารทะเล พวกเขาค่อย ๆ เยียวยาบาดแผลในใจ ผ่านผืนทะเลอันกว้างใหญ่และผู้คนอบอุ่นในชุมชนริมฝั่ง เรื่องราวสะท้อนการเริ่มต้นใหม่ ความฝันที่หล่นหาย และการค้นพบคุณค่าของชีวิตอีกครั้ง ท่ามกลางบรรยากาศทะเลสวยงามและความสัมพันธ์ที่ค่อย ๆ เติบโตอย่างอบอุ่น\r\n",
