    "titleTh": "The Eternal Fragrance หอมกลิ่นพันลี้ (2026) พากย์ไทย/ซับไทย EP.1-33",
    "titleEn": "The Eternal Fragrance หอมกลิ่นพันลี้ (2026) พากย์ไทย/ซับไทย EP.1-33",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/06/99-10.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/06/99-10.jpg",
    "videoUrl": "https://torbo007.com/embed/ad5d37e5a7ef2e10571d19b4c3256541",
    "sourceType": "embed",
    "description": "เรื่องย่อ: หอมกลิ่นพันลี้  | 千香引\r\n เมื่อเรื่องราวความลึกลับและความแปลกประหลาดจึงได้เริ่มต้นขึ้นในฝากฟ้า พร้อมการส่งผลให้กาลเวลาและความทรงจำของผู้คนบางคนต้องย้อนเวลากลับมาอีกครั้ง พร้อมการปลุกพลังโบราณที่หลับใหลมานานให้ตื่นขึ้นมาอีกครั้ง และความสนุกของซีรี่ย์เรื่องนี้ต้องบอกเลยว่าไม่ควรในการรับชมอย่างแน่นอน เรื่องราวเริ่มต้นเมื่อหนึ่งร้อยปี มีสาวกำพร้าผู้มีนามว่า เสี่ยวปังชุ่ย เมื่อเขาได้รับโอกาสเข้ามาร่ำเรียนในสำนักฝึกยุทธ์ของเหล่าเซียน แม้ว่าจะไม่มีชาติกำเนิดอันสูงส่งกันมาก่อน แต่เธอกลับมีพรสวรรค์และหัวใจอันบริสุทธิ์ ทำให้รู้จักกับเหล่าสหายร่วมสำนัก พร้อมหนุ่มเจ้าเล่ห์ผู้แสนเย็นชาอย่าง เหลยซิวหย่วน ชายหนุ่มผู็ที่เคยอยุ่เคียงข้างและเคยช่วยเหลือเธอในเวลายากลำบาก ทั้งสองค่อยๆสร้างสายสัมพันธ์อันแน่นแฟ้นมากขึ้นเรื่อยๆ ท่ามกลางการฝึกฝนและการร่วมผจญภัยร่วมกัน เมื่อเวลาผ่านไปนานแสนนาน ทุกคนต่างแยกย้ายกันไปเติบโต ในเส้นทางที่ตนเองเลือก กระทั่งห้าปีต่อมา เสี่ยวปังชุ่ย ได้ตักสินใจเปลี่ยนชื่อเข้ามาอยู่ในชื่อว่า เจียงลี่เฟย พร้อมการเติบดตเป็นหญิงสาวที่มีรูปร่างและหน้าตาอันงดงานอย่างไม่มีใครเทียบได้ จากความงามของเธอและกลิ่นหอมที่เป้นเอกลักษณ์ของเธอกลายเป็นจุดเลื่องลือไปทั่งยุทธภพ จนกระทั่งมีคนสงสัยในตัวตนที่แท้จริงของเธอ และเหตุใดหญิงสาวกลับมีพลังลึกลับ ที่สามารถดึงดูดผู้คนในใต้ล่า พร้อมการค้นพบตำนานของเหล่าเทพที่ถูกว่อนตัวอยู่มานานนับหมื่นๆปี\r\n",
