    "description": "เรื่องย่อ:เพลงรักแห่งคัชการ์ | 喀什恋歌\r\n เป็นอีกหนึ่งเรื่องที่เข้าบอกเล่าเรื่องราวของหญิงสาวทั้งสามคนที่กำลังออกเดินทางใช้ชีวิตกันคนละแบบ ทั้งเรื่องการงาน ความรัก และความฝัน ในเด็กสาวผู้อาศัยอยู่เมืองเล็กๆอย่างเมืองคัชการ์ ที่เต็มไปด้วยวัฒนธรรมและการเปลี่ยนแปลงทุกอย่าง และพวกเธอทั้งสามคนกลับต้องเรียนรู้ในการเริ่มต้นใหม่ ฟื้นฟูความสัมพันธ์ และค้นหาความหมายของชีวิต ในขณะคนหนึ่งที่กำลังก่อความเป็นความรักในท่ามกลางบรรยากาศความอบอุ่นของเมืองแห่งนี้ ท้ายที่สุดเรื่องราวการเติบโตของคนทั้งสามคนนี้จะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ สานต่อความสนุกไปพร้อมกันกับเราต่อได้ที่ ดูซีรี่ย์G4 มราเราพร้อมเสิร์ฟความมันส์ไปพร้อมคุณทุกๆที่คลิกเลย!!\r\n\r\n",
