    "description": "เรื่องย่อ:เพียงพบพาน ดั่งภาพฝัน | 人间惊鸿客\r\n“เมื่อโชคชะตานำพาให้คนสองคนกลับมาพบกันอีกครั้ง ท่ามกลางสงครามและความลับที่ซ่อนอยู่ The World Is Full of Surprises (เพียงพบพาน ดั่งภาพฝัน) จึงไม่ใช่แค่เรื่องรัก…แต่คือการต่อสู้ของหัวใจและชะตาชีวิต” เรื่องราวความวุ่นวายที่ได้เกิดขึ้นแห่งแคว้น “จิงหลาน” ซึ่งเป็นเผ่าพันธ์ที่ซึ่งสงครามและอำนาจเป็นตัวกำหนดชะตาชีวิตของผู้คน พร้อมการปรากฎตัวของ เซียงฉือ แม่ทัพหนุ่มผู้ยิ่งใหญ่ที่ทุกคนให้ฉายาว่าเป็น เทพสงครามม้าขาว ด้วยความบังเอิญเหล่านั้นกลับทำให้เขาได้มาพบกับ ฮั่นอวิ๋นหลิง หญิงสาวผู้มีความสามารถวิเศษในด้านการแพทย์ จากสถานการณ์ความวุ่นวายเหล่านั้นเอง ฮั่นอวิ๋นหลิง จึงถูกบังคับให้เข้าร่วมพิธีแต่งงานในช่วงเวลาคับขัน พร้อมทำให้ทั้งสองได้มาพบกันโดยความบังเอิญที่ไม่ใช่แค่ความบังเอิญเท่านั้น เพราะช่วงเวลาที่แท้จริงของทั้งสองกับมีอดีตที่เคยผูกพันกันมาก่อน ฮั่นอวิ๋นหลิง กลับเป็นเพียงคนเดียวที่สามารถช่วยเขาไว้ในวัยเด็ก ในช่วงเวลาที่ทั้งสองได้มาพบกันอีกครั้งกับเต็มไปด้วยความรู้สึกอันซับซ้อน และเมื่อความจริงที่เริ่มเปิดเผยมากขึ้นเรื่อยๆ กลับทำให้ ฮั่นอวิ๋นหลิงต้องเข้ามาพัวพันกับปัญหาการเมือง การใส่ร้ายครอบครัว และการต่อสู้เพื่อความยุติธรรม ของ เซียงฉือ ที่คอยรับมือต่อศัตรูภายนอกและพร้อมร้ายที่กำลังคุกคามในความรู้สึกเขามากในช่วงเวลานี้ ด้วยการตัดสินใจอันแน่วแน่จึงทำให้ทั้งสองต้องร่วมมือกัน ฝ่าฟันสงคราม พร้อมการเปิดโปรงความจริง และบ้านเมืองที่ติดอยู่ในท่ามกลางโลกที่ไม่มีความแน่นอนไม่ว่าจะเป็น ความรัก การเสียสละ และการต่อสู้เพื่อความจริงที่กำลังปรากฎขึ้นมาอีกครั้ง\r\n",
