    "sourceType": "embed",
    "description": "เรื่องย่อ-ทะลุมิติตะลุยวังหลวง | 成何体统\r\n เรื่องราวของเทพนิยายที่มีหญิงสาว หวังชุยฮวา ที่พบว่าตนเองอยู่ในร่างของหญิงสาวผู้อำนาจ เมื่อเธอได้มาพบกับ จางซาน ผู้ปกครองเมืองแต่เขากลับแอบซ่อนตัวตนมานานนักพันปี แต่โชคชะตากลับทำให้พวกเขาได้มาพบกับอีกครั้ง และในครั้งนี้ทั้งสองก็ได้ร่วมกันฝ่าฟันโชคชะตามที่โหดร้ายมานักต่อนักและพร้อมที่จะเข้ามาร่วมเปลี่ยนแปลงเรื่องราวในครั้งก่อน พร้อมเข้ามาเปิดเผยกับเหล่าศัตรูที่อยู่ในนิยายของเรื่องต่างก็ต้องเข้ามาส่อสู้กับทำนายอันโหดร้ายอย่างที่ว่าชีวิตของพวกเขาทั้งสองที่ไม่สามารถกลับมามองเหฌนโลกความจริงที่กำลังรุ่งโรจน์พร้อมถูกสร้างขึ้นโดยฝีมือของพวกเขาอย่างยากลำบาก ด้วยความใกล้ชิดของทั้งสองจะกลับกลายเป็นความรักที่สวยงามได้หรือไม่เราไปรับชมพร้อมๆกันค่ะ ต้องบอกเลยว่าซีรี่ย์เรื่องนี้เหมาะมากกับเพื่อนๆคนไหนที่ชื่นชอบในแนว ประวัติศาสตร์ , ปริศนา , โรแมนติก , แฟนตาซี ต้องถูกใจอย่างแรง และสามารถรับชมไปพร้อมกันได้แล้วในวันที่ 6 กุมภาพันธ์ 2026 โดยก็ได้มีกันทั้งหมด 32 ตอน พร้อมมาในรูปแบบซับไทย/พากย์ไทยให้ๆได้เลือกรับชมกันได้อย่างตามใจชอบแล้ว หากเพื่อนๆคนไหนที่กำลังมองหาซีรี่ย์เรื่องใหม่เอาไว้รับชมก็ไม่ควรพลาดกับ G4 แหล่งรวมซีรี่ย์ทุกประเภทนำมาไว้ที่ตรงนี้\r\n",
