    "videoUrl": "https://torbo007.com/embed/b556442b3cceeff730d0236a227cff28",
    "sourceType": "embed",
    "description": "เรื่องย่อ-Love Story in the 1970s\r\n บอกเล่าเรื่องราวของหญิงสาว “เฟยหนี่” ผู้มีฐานะธรรมดาๆคนหนึ่ง เมื่อเธอได้เข้ามาทำงาในโรงงานผลิตสินค้าแห่งหนึ่งของชุมชน เพียงเพราะจุดมุ่งหมายของเธอเพื่อที่จะส่งตัวเองเรียนจบเพื่อการเปลี่ยนแปลีงชีวิตและการเป็นอยู่ในตอนนี้ ด้วยความพยายามทุกอย่างของเธอ จึงทำให้เธอได้เลื่อนตำแหน่งและได้มาจบกับ “ฟางมู่หยาง” ชายหนุ่มผู้เป็นร่วมชั้นเรียนตั้งแต่วัยเด็ก ที่มีความกล้าหาญและความมุ่งมั่นตั้งแต่เด็กจึงทำให้เขาได้เรียนมหาวิทลัยดีๆมาโดยตลอด เพราะเหตุนี้ “เฟยหนี่” จึงเลือกที่จะขอความช่วยเหลือจากเขาอยู่เรื่อยมา และพร้อมให้ชายหนุ่มเข้าสอนการเรียนให้กับเธอ จนแล้วจนเล่าทุกอย่างกลับอยู่เพียงแค่จุดๆเดิม และทำให้เธอล้มลุมมาโดยตลอด แต่เธอยอมแลกทุกอย่างเพื่อความฝันที่ถูกตั้งมั่งเอาไว้ พร้อมทั้งรอบข้างของเธอยังมี “ฟางมู่หยาง” อยู่ข้างๆมาโดยตลอด และทั้งสองก็พร้อมที่จะต่อสู้กับการเป็นอยู่กับอนาคตที่กำลังจะมาถึง เมื่อความใกล้ชิดที่จะนำพาให้ทั้งสองพัฒนาเป็นความสัมพันธ์ที่ลึกซึ้งไปได้หรือไม่เราไปรับชมพร้อมๆกันค่ะ ",
