    "titleTh": "Bloody Flower คนแลกเลือด (2026) ซับไทย/พากย์ไทย EP.1-8",
    "titleEn": "Bloody Flower คนแลกเลือด (2026) ซับไทย/พากย์ไทย EP.1-8",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/02/1-1.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/02/1-1.jpg",
    "videoUrl": "https://torbo007.com/embed/8773b00ce10d5ef6dc764e610f93d463",
    "sourceType": "embed",
    "description": "เรื่องย่อ-Bloody Flower คนแลกเลือด (2026)\r\n เมื่อเกิดคดีฆาตกรรมต่อเนื่องที่ผู้ร้ายต้องการ “เหยื่อผู้บริสุทธิ์” มาเป็นแพะรับบาป เรื่องราวเริ่มต้นที่ อีอูกยอม ชายหนุ่มผู้เย็นชา ซึ่งคัดเลือกผู้คนจากโลกออนไลน์มาเป็นหนูทดลองในการรักษาลึกลับ แต่เมื่อการรักษาล้มเหลว เขากลับถูกตราหน้าว่าเป็นฆาตกร ท่ามกลางความสิ้นหวัง เขาได้พบกับ พัคฮยอนจุน ทนายความที่ต้องเข้ามารับผิดชอบคดีอื้อฉาวนี้ ทั้งสองกลายเป็นเป้าการสาปแช่งของสังคม ขณะเดียวกัน ชาอียอน อัยการสาวผู้ศรัทธาในความยุติธรรม พยายามไล่ล่าความจริงและกดดันให้อีอูกยอมสารภาพ การต่อสู้ระหว่างกฎหมาย ความโลภ และความหวังเพื่อชีวิตลูกสาวที่ป่วยหนัก จึงเริ่มต้นขึ้น สุดท้ายแล้ว ทั้งสามคนจะเลือกความถูกต้องหรือยอมจำนนต่อชะตากรรม เราต้องติดตามบทสรุปของคดีอันดำมืดนี้ไปพร้อมกัน สำหรับซีรี่ย์เรื่องนี้พร้อมจะพาแฟนๆไปดำดิ่งกับความมือของใจมนุษย์ แล้วในวันที่ 4 กุมภาพันธ์ 2026 เป็นต้นไป โดยก็ได้มีกันทั้งหมด 8 ตอนเพียงเท่านั้น พร้อมาในรูปแบบซับไทยหรืออาจจะมีพากย์ไทยต้องรอลุ้น สานต่อความสนุกและความเข้มข้มไปพร้อมๆกันกับเราได้ที่ G4 แหล่งรวมซีรี่ย์ออนไลน์ที่เรามีมากว่า สามพันกว่าเรื่อง>>\r\n",
