    "description": "เรื่องย่อ: ทนายสื่อวิญญาณ | 신이랑 법률사무\r\n เปิดต้นปีกันแบบฉ่ำๆ พร้อกับซีรี่ย์เกาหลีเรื่องใหม่ที่มีชื่อว่า “Phantom Lawyer ทนายสื่อวิญญาณ” พร้อมการบอกเล่าเรื่อวราวของตัวละครที่ไม่มีความสมบูรณ์แบบ เรื่องราวเปิดมาที่ “ชินอีรัง” ทนายผู้แสยเย็นชาในเมื่องเขาต้องมาพบกับเรื่องราวความวุ่นวาย พร้อมเหตุการณ์ที่เกี่ยวกับกลุ่มผีไม่น่ารัก ด้วยการเชื่อมั่นในเหตุการณ์ความยุติธรรมและความซื่อตรง ด้วยความซื่อตรงของเขาเองกลับทำให้ทุกอย่างล้มเหลวซ้ำแล้วซ้ำเล่า แต่แล้วเมื่อจุดเปลี่ยนแปลงที่สำคัญในครั้งนี้กลับทำให้เขาต้องมาพบกับ “อีรัง” เจ้าพนักงานสาวผู้เย็นชาและวันๆเธอพยายามและทุ่มเท่แต่กับเรื่องงานเพียงเท่านั้น ทว่าความจริงแล้วเธอกลับเป็นอีกหนึ่งคนผู้อยู่เบื้องหลังเกี่ยวกับหมอผีผู้น่าเกรงขาม ด้วยการเปลี่ยนแปลงพร้อมจุดเปลี่ยนที่ทำให้เธอเข้ามาปลดปล่อยพลังงานออกมาจากห้องมืด 501 และพร้อมเข้ามาต่อต้านกับเรื่องราวความแค้นในเหตุการณ์ครั้งนี้ ทั้งสองจึงได้ร่วมมือกันสืบหาเรื่องราวความจริงในคดีเหล่านี้ แต่แล้วจุดจบของทุกสิ่งทุกอย่างจะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ>>\r\n",
