    "sourceType": "embed",
    "description": "เรื่องย่อ: จุมพิตไซเรน | ese렌\r\n บอกเล่าเรื่องราวของเจ้าที่ตพรวจ “ชา อูซอก” เจ้าหน้าที่กำตวจที่พึ่งถูกย้ายจากที่ทำงานเดิม และในครั้งนี้กับดูเหมือนว่าทุอย่างจะทำให้เขาต้องเข้ามาพัวพันกับเรื่องราวปริศนาของเหตุการณ์ครั้งนี้ และจึงทำให้เขาได้มาพบกับ หญิงสาวผู้ต้องสงสัยที่ดูเหมือนว่าเธอจะเป็นหนึ่งในการก่อปริศนา ดูเหมือนว่าทุกอย่างจะเริ่มคลี่คลายคดีมากมายยิ่งขึ้น แต่เขากลับหลงใหลในความงามของ “ฮัน ซอล-อา” ที่ความงามของเธอกลับมีรู้ร่วมหน้าตาและเสน่ห์ความงามอย่างไร้ที่ติ แต่เธอกลับต้องตกใจเมื่อเธอได้รู้ว่าชายหนุ่มทุกคนที่เคยรักใคร่กับเธอต่างก็เสียชีวิตไปหมด แต่ในขณะเดียวกันนั้น “ชา อูซอก” จึงได้ลงมือออกตามหาความจริงด้วยตนเองและพร้อมจะเข้ามาเปิดโปร่งความจริงเรื่องราวของ “ไซเรน” ที่กำลังเกิดเรื่องราวร้ายๆมากในตอนนี้ แต่แล้ววันนนี้เขากลับได้รับสายปริศนาบางอย่างมากขึ้นพร้อมทุกอย่างกลับทำให้เขาต้องสั่น คลอนมากยิ่งขึ้นและพร้อมที่จะเข้ามาสืบหาตัวตนของ “ฮัน ซอล-อา” ที่เป้นที่ต้องสงสัยในคดีฆาตกรรมครั้งนี้ ทว่าเรื่องราวความสั่นคลอนของซีรี่ย์เรื่องนี้ตจะเป็นอย่างไรเราไปรับชมพร้อมกันค่ะ หากเพื่อนๆคนไหนที่กำลังมองหาซีรี่ย์เรื่องอื่นๆเอาไว้รับชมก็ไม่ควรพลาดกับ G4 แหล่งรวมซีรี่ย์ออนไลน์ที่เรามีมากกว่าสามพันกว่าเรื่อง บอกเลยว่าห้ามพลาดเลยจริงๆ \r\n",
