    "description": "เรื่องย่อ-เอไอไขรัก\r\n เมื่อเรื่องราวความวุ่นวายทุกอย่างที่กำลังจะเกิดขึ้น ดูบีอา หญิงสาวคนหนึ่งที่ได้เข้ามาเป้นตัวแทนของแอปหาคู่ที่ใครหลายๆคนต่างนำมาใช้งานกับอยู่ตลอดเวลา ดูเหมือนว่าหน้าที่ในการทำงานของเธอมักจะเป็นหน้าที่สำคัญ และการรองรับอารมณ์ของคนหมู่มาก พร้อมทำให้เธอต้องบอมซ้ำน้าใจมาโดยตลอด ด้วยการศึกษาและการหาวิธีการแก้ไขปัญหาและ ดูบีอา กลับมองเห็นว่าเทคโนโลยรเครื่องนี้ก็เป็นอีกเครื่องที่ทันสทัยและตอบโจทย์คนในยุคนี้ได้เป็นอย่างดี แต่แล้วด้วยความสามารถที่ไม่เพียงพอจนทำให้เธอได้เข้ามาของความช่วยเหลือกับ ฮอลซอนโฮ นักเขียนมืออาชีพที่เขาเป็นนักเขียนเกี่ยวกับผลงานและเรื่องราวความรัก ที่เหล่านักอ่านกำลังนิยมกันในตอนนี้ จากความพยายามของเขาที่ทำให้ผลงานที่ทำมาและได้ขายหมดภายในระยะเวลาเพียงแค่หนึ่งเดือนเท่านั้น ทว่าเขากลับเป็นบุคคลที่เกลียดแอปหาคู่เป้นอย่างมาก แต่ทั้งสองกลับต้องจำเข้ามาร่วมงานกันอีกครั้ง และพร้อมที่จะเข้ามาออกแบบแอปหาคู่ออกมาได้อย่างสมบูรณ์แบบอีกครั้ง แต่แล้วจนเล่าดูเหมือนว่าทุกอย่างที่จะเริ่มมีความขัดแย้งต่อกันมากขึ้น ยุนบีอา กลับพยายามทำให้ชายหนุ่มได้มองเห็นถึงความรักที่แสนงดงานและความต้องการความรักที่ไม่ได้เกิดขึ้นมาพร้อมกับความสมบูรณ์แบบ แต่แล้วจุดจบของซีรี่ย์เรื่องนี้จะเป็นอย่างไรเราไปรับลุ้นพร้อมๆกันค่ะ สานต่อความนสนุกและความเข้มข้นไปพร้อมๆกันกับเราได้ที่ G4 แห่งรวมซีรี่ย์ออนไลน์ที่เรามีมากกว่าสามพันเรื่อง\r\n ",
