    "titleTh": "The Legend of Rosy Clouds บุปผาคู่บัลลังก์ (2026) พากย์ไทย/ซับไทย EP.1-36",
    "titleEn": "The Legend of Rosy Clouds บุปผาคู่บัลลังก์ (2026) พากย์ไทย/ซับไทย EP.1-36",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/06/9-9.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/06/9-9.jpg",
    "videoUrl": "https://torbo007.com/embed/60f8d128c2676e6415dc9f428ca9f4f4",
    "sourceType": "embed",
    "description": "เรื่องย่อ: บุปผาคู่บัลลังก์ | 云秀行❤️‍🔥\r\n เล่าเรื่องราวในดินแดนสมมติที่เต็มไปด้วยการแก่งแย่งอำนาจและความขัดแย้งทางการเมือง บอกเล่าเรื่อวราวของ ฟ่านอวิ๋น หญิงสาวจากตระกูลขุนนาง ที่อดีตเคยรุ่งเรืองมาก่อน แต่แล้วเธอต้องดิ้นรนใช้ชีวิตในท่ามกลางความยากลำบากแม้ว่าจะเป็นสตรีก็ตามแต่ ในครั้งนี้เธอกลับมีสติปัญญา ความกล้าหาญ และอุดิการณ์ในการช่วยเหลือผู้คนที่อยู่ในการปกครอง จนทุกอย่างทำให้เธอเข้ามาพัวพันกับการเมือง ท่ามกลางความวุ่นวายเหล่านี้กลับทำให้เธอได้มาพบกับ ฉีเจิ้ง หนุ่มเจ้าเมืองที่เฉลียวฉลาดและเต็มไปด้วยเล่ห์เหลี่ยมทางการเมือง ในช่วงแรกทั้งสองต่างไม่ไว้วางใจกัน แต่เมื่อเผชิญหน้าและวิกตแผนการสมคบคิดมากมาย พวกเขาทั้งสองจึงร่วมมือกันต่อสู้เพื่อความสงบสุขของแผ่นดิน ความสัมพัน์ที่ร่วมือค่อยๆ พัฒนามิตรภาพ ความเชื่อใจ และความรักอันลึกซึ้ง ท่ามกลางการต่อสู้การแย่งชิงอำนาจ การก่อกบฎ และปัญหาของประชาชน ฟ่านอวิ๋น ต้องพิสูจน์คุณค่าตัวตนของตนเอง ที่ผู้หญิงทั้งเมืองต่างกูกจำกัดบทบาท ขณะที่ ฉีเจิ้ง ที่พยายามต่อสู้กับศัตรูทางการเมือง และชะตากรรมของบ้านเมือง ทั้งคุ่ต่างร่วมมือกันฝ่าฟันอุปสรรค เพื่อการสร้างความเจริญรุ่งเรืองให้แคว้นเมืองเก่าอีกครั้ง \r\n",
