    "description": "พล็อตเรื่อง:ปริศนาชราชน\r\n เรื่องราวของกลุ่มวัยชราที่ต้องออกโรงปกป้องเมืองที่อยู่อาศัยอันเงียบสงบในช่วงเวลานี่ แต่ในระหว่างการออกสืบหาความจริงภายใต้เมืองอันเงียบสงบ กับการทดลองเทคโนโลยีที่ทันสมัย และทุกอย่างจะเป็นการเปลี่ยนแปลงชีวิตของพวกเขาทุกคนไปตลอดกาล ในขณะเดียวกันนั้นแต่ละคนก็ต้องเผชิญหน้ากับความจริงที่แสนเจ็บปวด การสูญเสียและความกลัวในวัยชรา สำหรับซีรี่ย์เรื่องนี้ก็เป็นอีกหนึ่งเรื่องที่โดดเด่นด้วยบรรยากาศลุ้นระทึก ผสมดราม่าอบอุ่นและมิตรภาพของเหล่าผู้สูงวัย ที่แม้แต่อายุจะมากหรือน้อยนักก็ตาม สรุกแล้วเรื่องราวทุกอย่างจะตัดจบไปอย่างไเราไปรับชมพร้อมๆกันค่ะ\r\n",
