    "sourceType": "embed",
    "description": "เรื่องย่อ:ศัตรูหัวใจ นางร้ายวังหลวง | 멋진신세계\r\n เรื่องราวของ คังดันซิม นางร้ายผู้โด่งดังแห่งยุคโชซอน หญิงสาวที่เต็มไปด้วยความทะเยอทะยานและเล่ห์เหลี่ยม เธอใช้ทุกวิถีทางเพื่อไต่เต้าขึ้นสู่ตำแหน่งสนมเอกในวังหลวง จนในที่สุดกลับต้องจบชีวิตลงอย่างน่าเศร้าด้วยการถูกลอบวางยาพิษ ทว่าชะตาชีวิตของเธอยังไม่สิ้นสุด เมื่อวิญญาณของดันซิมได้ฟื้นคืนขึ้นมาอีกครั้งในปี 2026 และเข้าไปอยู่ในร่างของ ชินซอรี นักแสดงสาวโนเนมในโลกยุคปัจจุบัน จากนางร้ายผู้เคยควบคุมเกมการเมืองในวัง กลับต้องมาเผชิญกับโลกใหม่ที่เต็มไปด้วยเทคโนโลยีและกฎเกณฑ์ที่ไม่คุ้นเคย แม้ทุกอย่างจะเปลี่ยนไป แต่ไหวพริบและความเจ้าเล่ห์ของเธอยังคงอยู่ และนั่นทำให้ชีวิตของซอรีไม่เหมือนเดิมอีกต่อไป ในเวลาเดียวกัน เธอได้พบกับ ชาซีกเย ทายาทมหาเศรษฐีผู้เย็นชา ชายหนุ่มที่ใช้เหตุผลและผลประโยชน์เป็นที่ตั้ง ความสัมพันธ์ของทั้งคู่เริ่มต้นจากการเป็นคู่ปรับ เต็มไปด้วยการปะทะคารมและเกมจิตวิทยา ก่อนจะค่อย ๆ แปรเปลี่ยนเป็นแรงดึงดูดที่ยากจะต้านทาน ท่ามกลางความวุ่นวายของโลกปัจจุบัน ดันซิมต้องเผชิญทั้งอดีตที่ตามหลอกหลอน และโอกาสครั้งใหม่ในการเปลี่ยนแปลงชะตาชีวิตของตัวเอง ขณะที่ความสัมพันธ์ระหว่างเธอกับซีกเยก็ค่อย ๆ พัฒนาเป็นความรักที่ทั้งซับซ้อนและยากจะคาดเดา\r\n",
