    "sourceType": "embed",
    "description": "พล็อตเรื่อง:ทนายสามสาวฉาว | 아너\r\n เรื่องราวของทนายสาวสุดแกร่ง 3 คนที่เป็นเพื่อนกันมายาวนานกว่า 30 ปี  พวกเธอเติบโตมาพร้อมความเชื่อมั่นในกฎหมายและความยุติธรรมอย่างแรงกล้า  ก่อนจะจับมือกันก่อตั้งสำนักงานกฎหมายชื่อดัง และเลือกทำคดีเพื่อผู้หญิงโดยเฉพาะ  ไม่ว่าจะเป็นเหยื่อที่ถูกกดขี่หรือไม่ได้รับความเป็นธรรม พวกเธอพร้อมสู้จนถึงที่สุด ชื่อเสียงและความสำเร็จในหน้าที่การงาน ทำให้พวกเธอกลายเป็นที่ยอมรับในวงการ แต่เบื้องหลังภาพลักษณ์อันสมบูรณ์แบบ กลับซ่อนความลับในอดีตเมื่อ 20 ปีก่อน  ความจริงที่ทั้งสามพยายามปกปิด เริ่มค่อย ๆ ถูกเปิดเผยขึ้นอย่างหลีกเลี่ยงไม่ได้  มันไม่เพียงสั่นคลอนชื่อเสียง แต่ยังทำให้มิตรภาพที่แน่นแฟ้นเริ่มแตกร้าว  เมื่ออดีตตามหลอกหลอนถึงปัจจุบัน ทุกอย่างที่เคยสร้างมาเสี่ยงพังทลาย สุดท้ายแล้ว พวกเธอจะเลือกยืนหยัดเพื่อความจริง หรือปกป้องเพียงตัวเองกันแน่…\r\n",
