    "description": "เรื่องย่อ- Reverse | 리버스\r\n เมื่อเรื่องราวอันลึกลับที่กลุ่มเพื่อนต้องหาวิธีการแก้เรื่องราวทุกอย่างให้ออกมาสำเร็จอีกครั้ง บอกเล่าเรื่องราวของ มดยจิน หญิงสาวธรรมดาๆคนหนึ่งที่ได้รับอุบัติเหตุ ในครั้งที่วิลล่าไฟไหม้ในครั้งก่อน จึงทำให้เธอสูญเสียความทรงจำไปอย่างกระทันหัน ในความวุ่นวายเหล่านั้นกลับทำให้เธอได้มาพบกับคู่หมั้นคนต่อไป ซึ่งเขากลับเป็นประธานคนใหม่ต่างก็กำลังมองเธอมาโดยตลอด แต่แล้ว มโยจิน กลับไม่สามารถเอาชีวิตรถจากเหตุการณไฟไหม้ครั้ง พร้อมจึงทำให้ จุนโฮ ก็ได้เข้ามาดูแลเธออย่างใกล้ชิดกันมากขึ้น สุดท้ายแล้วจุจบของซีรี่ย์เรื่องนี้จะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ ต้องบอกเลยว่าซีรี่ยืเรื่องนี้ตอบโจทย์กับเพื่อนๆคนไหนที่ชื่นชอบในแนว ลึกลับ | เมโลดราม่า | ระทึกขวัญ บอกเลยว่าไม่ควรพลาดกับซีรี่ย์เรื่องนี้อย่างแน่นอน…    \r\n",
