    "description": "เพราะใจยังมีเธอ ซับไทย เรื่องราวเริ่มต้นที่ ซือฉิงเย่, ประธานหนุ่มหล่อของบริษัทซือซื่อกรุ๊ป, ที่กำลังมีความรักอันแสนหวานกับ หนิงอู๋หุ่ย แต่ความรักของพวกเขากลับต้องเผชิญกับปัญหาเมื่อถูกคนชั่ววางแผนให้เกิดความเข้าใจผิด ทำให้พวกเขาต้องเลิกรากันไปอย่างไม่ดีนัก นอกจากนี้ หนิงอู๋หุ่ย ยังตั้งครรภ์ลูกของซือฉิงเย่อีกด้วย\r\n\r\nต่อมา เธอเกิดอุบัติเหตุอย่างกระทันหันที่ทำให้เสียความทรงจำทั้งหมด และต้องใช้ชีวิตเพียงลำพังในการคลอดลูกและเลี้ยงดูพวกเขา จนเวลาผ่านไปถึง 7 ปี ทั้งคู่ได้พบกันอีกครั้ง\r\n\r\nในครั้งนี้ ซือฉิงเย่ จะสามารถแก้ไขความเข้าใจผิดและฟื้นฟูความรักที่เคยมีได้หรือไม่? ต้องรอลุ้นไปพร้อมกันในเรื่องนี้!",
