    "videoUrl": "https://torbo007.com/embed/30d417968fb098268e983c9419e6c52a",
    "sourceType": "embed",
    "description": "เรื่องย่อ:กีรีโก แอปหลอน พรสั่งตาย | 기리고 \r\n “หากมีเพียงรข้อเดียวที่สามารถขออะไรก็ได้ แต่สุดท้ายแล้วผลลัพธ์ทุกอย่างกลับต้องแลกด้วยชีวิต”  บอกเล่าเรื่องราวความสยองขวัญของกลุ่มเพื่อนทั้งห้าคนที่กำลังศึกษาอยุ่ไฮสคูลมานานนับ 4 ปี ทว่าเรื่องราวความวุ่นวายและความสับสนได้กลับมาอีกครั้ง เมื่อมีกลุ่มเพื่อนเข้าไปพัวพันกับการเสียชีวิตอย่างกระทันหัน ซึ่งทุกอย่างเริ่มต้นมาพร้อมกับเดอะแก๊งทั้ง 5 คนนี้ แต่ด้วยความพยายามตามหาความจริงที่มีใครบางคนเก็บซ่อนเอาไว้ ด้วยความเป้นจริงและเบื่องหลังอันน่ากลัว พร้อมด้านมืดที่กำลังขุดสร้างขึ้น และความชิปหายจึงได้เริ่มต้นขึ้นกับ (แอป) ที่กำลังพยายามเข้ามาล้างสมอง พร้อมการตั้งคำถามเกี่ยวกับผู้ใช้งานจริง แต่สุดท้ายแล้วซีรี่ย์เรื่องนี้จะจบลงอย่างไรเราไปรับชมพร้อมๆกันค่ะ>> ",
