    "sourceType": "embed",
    "description": "เรื่องย่อ-แผนล่าท้าคนโลภ | 골드랜드💰🔥\r\n “ถ้าความฝันถึง “เงินก้อนโต” คือจุดเริ่มต้นของทุกอย่าง…ซีรีย์ Gold Land แผนล่าท้าคนโลภ เรื่องนี้จะค่อยๆ ฉีกให้เห็นว่า ความโลภของมนุษย์มันน่ากลัวกว่าศัตรูคนไหน—และไม่มีใครรอดออกไปได้แบบเดิมอีกเลย” เรื่องราวของ “คิมฮีจู” หญิงสาวธรรมดาที่พยายามหนีจากชีวิตเดิมในชนบทเพื่อเริ่มต้นใหม่ในเมืองใหญ่ ชีวิตของเธอกำลังไปได้สวย ทั้งงานในสนามบินและความรักกับแฟนหนุ่มนักบิน แต่ทุกอย่างกลับพลิกผัน เมื่อเธอถูกดึงเข้าไปพัวพันกับขบวนการลักลอบขนทองคำโดยไม่รู้ตัว จากคนธรรมดา ฮีจูกลายเป็น “กุญแจสำคัญ” ในเกมล่าทองคำมูลค่ามหาศาล และต้องหนีเอาชีวิตรอดพร้อมทองคำแท่งที่เต็มไปด้วยอันตราย ขณะที่องค์กรอาชญากรรมและผู้คนมากมายต่างออกตามล่าเธออย่างไม่ลดละ ฮีจูต้องหลบหนีเอาชีวิตรอด พร้อมกับทองคำที่ใคร ๆ ก็ต้องการ ขณะเดียวกันก็ถูกไล่ล่าจากทั้งองค์กรอาชญากรรมและผู้คนที่เต็มไปด้วยความโลภและการหักหลัง สุดท้ายแล้วจุดจบของเรื่องจะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ  ",
