    "description": "เรื่องย่อ นักสืบขวัญใจมหาชน (2026)\r\n บอกเล่าเรื่องราวของตำรวจอย่าง เฉินเจียเริ่น ที่ต้องพยายามตามล่ากับกลุ่มวิสามัญฆาตกรรมอินฟลูเอนเซอร์ชื่อดังระดับประเทศอย่าง เหวินเยี่ยน ดูเหมือนทุกอย่างจะเข้าทางโจรไปซะทุกทาง จนกระทั่งเขาได้มาพบกับ แม่มดบาบา ผู้ที่เข้ามาทำนายโชคชะตาของเขาไปในทางที่ไม่ดีซักเท่าไหร่ เพราะคำพูดของเขาที่ดุเหมือนว่าทุกคนจะไม่ค่อยชื่นชอบต่างก้เข้ามารุ่มด่าต่อว่าเธออยุ่ตลอดเวลา เฉินเจียเริ่น จึงเริ่มตัดสินใจว่าจะลงมือตรวจสอบด้วยตนเอง แต่ดูเหมือนว่าหญิงสาวจะมาแอบซ่อนอะไรบ้างอย่างเอาไว้และเป้นเบาะแสชิ้นสำคัญที่ลามไปถึงแม่มดบาบาที่ทำนายการตายของเหล่าคนดังได้อย่างแม่นยำต่อเนื่อง ทุกอย่างที่เกี่ยวข้องกับคดีนี้ก็เชื่อมโยงไปที่ความขัดแย้งในโลกออนไลน์ หรืออาจจะเป็นเรื่องราวอื่นที่พยายามส่งผลกระทบและทำให้เธอตัดสินในที่จะXายตัว...อย่างที่สุด แต่แล้วจุดจบของซีรี่ย์เรื่องนี้จะเป็นอย่างไรสามารับชมกันต่อได้ที่ G4 แหลางรวมความสนุกและความเข้มน้ ครบ จบ ในที่เดียว  \r\n\r\n",
