    "sourceType": "embed",
    "description": "เรื่องย่อ-คนจริงเผาแค้น\r\nจอห์น เครซี่ อดีตเจ้าหน้าที่ CIA ผู้หมดศรัทธาในชีวิต เดินทางมายังเม็กซิโกเพื่อเริ่มต้นใหม่ เขาได้รับงานเป็นบอดี้การ์ดให้ “พิต้า” เด็กหญิงลูกสาวของครอบครัวเศรษฐี ในตอนแรกเครซี่เป็นคนเงียบขรึมและห่างเหิน แต่พิต้าค่อย ๆ ทำให้เขาเปิดใจอีกครั้ง ความสัมพันธ์ของทั้งคู่พัฒนาเป็นความผูกพันที่ลึกซึ้งเหมือนพ่อกับลูก วันหนึ่งพิต้าถูกลักพาตัวไปต่อหน้าต่อตาเครซี่ ทำให้เขารู้สึกผิดอย่างหนัก หลังจากพยายามช่วยเหลือแต่ล้มเหลว เครซี่เชื่อว่าพิต้าเสียชีวิตแล้ว เขาตัดสินใจออกตามล่าคนร้ายอย่างโหดเหี้ยมเพื่อทวงความยุติธรรม เครซี่ใช้ทุกวิธีการ ไล่ล่าทั้งแก๊งอาชญากรและผู้มีอิทธิพลที่อยู่เบื้องหลัง ระหว่างทางเขาค้นพบความจริงบางอย่างเกี่ยวกับการลักพาตัวครั้งนี้ เรื่องราวจบลงด้วยการเสียสละครั้งใหญ่ของเครซี่ เพื่อแลกกับชีวิตของพิต้าและไถ่บาปของตนเอง\r\n",
