    "description": "เรื่องย่อ: อย่างนี้ต้องโดนสั่งสอน | 참교육🪴\r\n เรื่องราวเกิดขึ้นในช่วงเวลาที่ปัญหาความรุนแรงในโรงเรียนทวีความรุนแรงขึ้น ครูจำนวนมากสูญเสียอำนาจในการควบคุมนักเรียน จนรัฐบาลต้องจัดตั้งหน่วยงานพิเศษที่ชื่อว่า สำนักงานคุ้มครองสิทธิทางการศึกษา (ERPA) ขึ้นมาเพื่อจัดการกับปัญหาเหล่านี้โดยตรง แต่แล้ว นาฮวาจิน เจ้าหน้าที่ตำรวจหัวกระทิของหน่วยงานชื่อดัง กลับพยายามหาวิธีการแก้ปัญหาที่เด็ดขาดและไม่ยึดติดกับกฎหมายแบบดั้งเดิม นาฮวาจิน เพื่อเข้ามาเรียนในโรงเรียนอันธพาล กลุ่มผู้มีอิทธิพล และระบบทุกอย่างเติมไปด้วยการทุจริต เพื่อการทวงคืนความยุติธรรมให้กับผู้ที่ตกเป็นเหยื่อ ไม่ว่าจะเป็นครูหรือคนที่เกี่ยวข้องกับปัญหาเหล่านี้ทั้งหมด เมื่อการตัดสินด้วยคำพูดที่ไม่สามารถเปลี่ยนแปลงคนได้อีกต่อไป เข้ากลับเลือกวิธีการอันเข้มข้นมากยิ่งขึ้น และทุกอย่างกลับนำไปสู่ปัญหา และการเผชิญหน้าอันดุเดือด\t",
