    "titleTh": "จีน Fate Chooses You คู่สรรสวรรค์สร้าง (2026) พากย์ไทย/ซับไทย EP.1-40",
    "titleEn": "จีน Fate Chooses You คู่สรรสวรรค์สร้าง (2026) พากย์ไทย/ซับไทย EP.1-40",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/04/9-12.jpg",
