    "videoUrl": "https://torbo007.com/embed/76804139e8d0d4badac800d0325f1d2c",
    "sourceType": "embed",
    "description": "พล็อตเรื่อง:คู่สรรสวรรค์สร้าง | 佳偶天成 \r\n  “เมื่อโชคชะตากำหนดให้พวกเขาต้องมาต่อสู้กับความวุ่นวาย พร้อมสงครามอันนองเลือดที่ถูกสร้างขึ้นด้วยคำสัญญาณที่อดีตไม่สามารถทำได้สุดท้ายแล้วทุกอย่างต้องตกมาสู่รุ่นลูก” บอกเล่าเรื่องราวถึงความขัดแย้งที่เริ่มต้นด้วยการล้างแค้นของแต่ละเผ่าพันธุ์ แต่สุดท้ายแล้วทุกอย่างกลับต้องตกมาสู่รุ่นลูกอย่างท้ายที่สุด และดูเหมือนว่าโชคชะตาได้เล่นตลกให้พวกเขาอีกครั้ง เมื่อเผ่าจ้ายกุยที่กำลังดับหายไปอย่างสิ้นสุด ทว่าเมื่อมีชายหนุ่มปริสนาที่ปรากฎตัวขึ้นมาจากความวุ่นวาย ลู่เซียนเฉียว และพร้อมเข้ามาสานต่อพันธสัญญา แต่หากรู้หรือไม่ว่ายังมีหญิงสาวอย่าง ซินเหมย ซึ่งก็ถูกกำหนดในการผูกสัญญาในครั้งนี้ แต่ดูเหมือนว่าเมื่อทั้งสองได้มาพบกันอีกครั้ง ต่างฝ่ายต่างไม่ลงรอยซึ่งกันและกัน แต่สุดท้ายแล้วทั้งสองก็พร้อมจับมือกันร่วมฝ่าฟันอุปสรรคในครั้งนี้ไปได้ เมื่อความใกล้ชิดที่กลับกลายเป็นความสัมพันธ์อันลึกซึ้งครั้งใหม่อีกครั้ง....",
