    "titleTh": "Dream of Golden Years ยุคทองของคนมีฝัน (2026) พากย์ไทย EP.1-36",
    "titleEn": "Dream of Golden Years ยุคทองของคนมีฝัน (2026) พากย์ไทย EP.1-36",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/03/1-2.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/03/1-2.jpg",
    "videoUrl": "https://torbo007.com/embed/5fd34a6e9389a88637815edeb748b287",
    "sourceType": "embed",
    "description": "เรื่องย่อ:-Dream of Golden Years\r\n วันนี้เราจะพาทุกคนย้อนกลับไปเมื่อปี 1983 ในช่วงยุคสมัยที่เริ่มมีการเปลี่ยนแปลง พร้อมธุรกิจที่เริ่มจางหายและเปลี่ยนแปลงเป็นการแข็งขันมาขึ้นเรื่อยๆ แต่กลับมีเพียงหญิงสาวคนเดียวเท่านั้นที่พยายามดิ้นรนและต่อสู้กลับปัญหา และข่าวลือที่ต่างก็ต้องมาพบเจอชีวิตที่ดูเหมือนว่าทุกอย่างจะไม่ค่อยราบรื่นมากเท่าไหร่ จากความล้มเหลวทุหอย่างกลับทำให้เธอได้ตัดสินใจฮึดขึ้นสู้อีกครั้งในท่ามกลางความยากลำบาก และความท้าทาย ต่างก็ดิ้นรนและไม่ย้อท้อกับการลงทุนในธุรกิจอีกครั้ง ด้วยการต่อสู้ที่เติมไปด้วยการแข่งขันกลับทำให้ชีวิตของหญิงสาวเริ่มดีขึ้นเรื่อย เพราะมีชายหนุ่มก้าวเข้ามาร่วมจับมือต่อสู้กับความยากลำบากในครั้งนี้ แต่สุดท้ายและเรื่องราวของชีวิตของหญิงสาวคนนี้จะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ จากความสุขและความสดใสของหญิงสาวที่ยังไม่สิ้นสุด และสามารถรับชมความสนุกกันต่อได้ที่ G4 ดูซีรี่ย์จีนซับไทยอัปเดตตอนใหม่ \r\n",
