    "titleTh": "คดีพิศวงเสียงกระซิบในหมอก Unveil:Jadewind (2026) ซับไทย-พากย์ไทย EP1-40",
    "titleEn": "คดีพิศวงเสียงกระซิบในหมอก Unveil:Jadewind (2026) ซับไทย-พากย์ไทย EP1-40",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/02/9-2.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/02/9-2.jpg",
    "videoUrl": "https://torbo007.com/embed/288e751577f8c37c771025521c107dd3",
    "sourceType": "embed",
    "description": "เรื่องย่อ: คดีพิศวงเสียงกระซิบในหมอก | 唐宫奇案之青雾风鸣    \r\n ในค่ำคืนที่ทุกคนมีความสุขแต่ความสุขเหล่านั้นต้องหายไปอย่างกระทันหัน เมื่อเรื่องราวการตายของบุตรสาวผู้มีอำนาจในการครอบครองเมืองไปตุยไปอย่างปริศนา เพราะเหตุนี้เอง หลี่เพ่ยอี๋ จึงถูกเข้ามาสืบหาเรื่องราวความจริงที่ได้เกิดขึ้น แต่ความที่ว่าคนเดียวก้ไม่สามารถสู้กับคนหมู่มากได้ เธอจึงได้เลือกที่จะมาพบกับ เสี่ยวหวยจิน ผู้ทำนายความที่ไม่หวังพึ่งเงินบทองที่และพร้อมที่จะยึดมั่นในความดี เมื่อทั้งสองได้มาพบกับและได้ตัดสินใจร่วมมือกันในการแก้ปัญหาในคดีฆาตรกรรมที่เกี่ยวกับราชสำนักดุเหมือนว่าหลักฐานทุกอย่างจะชี้นำไปที่ความเหล่าขุนนางผู้มีอำนาจและกำลังบงการเรื่องราวทั้งหมดนี้ ด้วยความร่วมมือของคนทั้งสองพวกเขาจะสามารถแก้ไข้ปัญหาเหล่านี้ได้หรือไม่เราไปลุ้นพร้อมๆกันค่ะ หากเพื่อนๆคนไหนที่กำลังมองหา เว็บดูซีรี่ย์ จีน เกาหลี ฝรั่ง บอกได้เลยว่าไม่คสรพลาดกับ G4 แหล่งรวมความบันเทิงที่ ครบ จบ ในที่เดียว \r\n",
