    "titleTh": "Veil of Shadows บันทึกเกล็ดจันทร์ (2026) ซับไทย/พากย์ไทย EP.1-29",
    "titleEn": "Veil of Shadows บันทึกเกล็ดจันทร์ (2026) ซับไทย/พากย์ไทย EP.1-29",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/03/999-1.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/03/999-1.jpg",
    "videoUrl": "https://torbo007.com/embed/a66d119758367d7f236777618e90f43a",
    "sourceType": "embed",
    "description": "พล็อตเรื่อง-บันทึกเกล็ดจันทร์ | 月鳞绮纪✨🔥\r\n เรื่องราวการแก้แค้นที่ต้องกลับกลายเป็นความรักที่กำลังผลิบานอีกครั้ง” บอกเล่าเรื่องราวของ “ลู่อู๋อี” ทายาทสาวเพียงคนเดียวของเผ่าจิ้งจองที่ได้เติบโตมาด้วยความอบอุ่น แต่เมื่อเธออายุครบรอบที่ต้องออกเดินทางล่าปีศาจ และพยายามปกป้องฟูงจิ้งจองให้เผ่าของเธอสงบสุข แต่แล้ววันหนึ่งเมื่อ “ลู่อู๋อี” ต้องมาพบเจอกับจุดเปลี่ยนแปลงของชีวิตอีกครั้ง เมื่อเธอได้มาพบกับ “อู่สือกวง” ปีศาจหนุ่มผู้บำเพ็ญเพียรมานับสิบปี ด้วยการสืบหาความจริงเหล่านี้ เธอกลับเลือกที่จะปลอมตัวเข้ามาเข้ามาตามหาความจริงที่ถูกเก็บซ่อนเอาไว้ แต่เมื่อเธอได้มาพบกับ “อู๋สือกวง” บุคคลผู้ต้องคนสาปและมีอดีตอันลึกลับ แต่ด้วยความหวาดระแวงเหล่านั้นกลับทำให้ทั้งสองได้โคจรมาพบกันอีกครั้ง เพียงเพราะความทรงทำของทั้งสองที่เริ่มมีอะไรเหมือนๆกันกลับทำให้ทั้งสองเริ่มตั้งความสัมพันธ์อันลึกซึ้งมายิ่งขึ้น เมื่อความวุ่นวายที่เริ่มต้นขึ้นกับความเป็นจริงของแต่ละคนที่ต้องยอมรับ และหญิงสาวต้องเลือกระหว่างการสืบหาความจริงหรือความรักที่ทั้งสองพึ่งเริ่มสานต่อความสัมพันธ์เหล่านนี้ สานต่อความสนุกและความเข้มข้นของซีรี่ยืเรื่องนี้ต่อไปพร้อมกันกับเราได้ที่ G4 แหล่งรวมซีรี่ย์ออนไลน์ที่เรามีมากกว่าสามพันเรื่อง เรียกได้ว่าครบ จบ ในที่เดียวเลยจริงๆ>>  \r\n",
