    "titleTh": "Generation To Generation ทิวากลางแห่งพิรุณโปรย (2026) ซับไทย/พากย์ไทย EP.1-37",
    "titleEn": "Generation To Generation ทิวากลางแห่งพิรุณโปรย (2026) ซับไทย/พากย์ไทย EP.1-37",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/02/9-8.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/02/9-8.jpg",
    "videoUrl": "https://torbo007.com/embed/4a5f4938291e0e8d1e9ea7f0f1399a08",
    "sourceType": "embed",
    "description": "บทสรุปของเรื่อง: ทิวากลางแห่งพิรุณโปรย | 江湖夜雨十年灯\r\n บอกเล่าเรื่องราวของ เซ่งเจา หญิงสาวจากตระกูลที่ถูกทุกคนต่อว่าเสียๆหลายๆมากมาย พร้อมการด่าว่าเธอเป็นปีศาจที่คอยกัดกินชีวิตของคนในหมู่บ้าน แต่แล้วเธอจึงได้เดินทางเข้ามาขอเป็นศิษย์ของเขจ้าสำนักชื่อดังอย่าง ซิงหนิงจง เจ้าสำนักแห่งยุทธภพที่ใครๆก็ต่างเกรงกลัวเขาโดยตลอด แต่เมื่อเธอได้มาพบกับ จิ้งหนิงได้มาพบกับอีกครั้งต่างก็ได้ถึงถึงเรื่องราวในวัยเด็กที่ต่างก็ได้พบเจอเรื่องราวต่างๆได้อย่างโหดร้าย จนกระทั่งเจ้าสำนักกับนำเขามารับเลี้ยงเหมือนลูกที่แท้ๆ ทั้งสองจึงเติบโตมาด้วยกันแต่ต่างคนก็ต่างมีนิสัยไปคนละขั้ว เพราะโชคชะตามที่ถูกกำกหนดเอาไว้ให้กลายเป็นผู้ที่เเข็งแกร่งและเพราต่อต้านชะตากรรมที่ถูกกำหนดเอาไว้ แต่แล้ววันหนึ่งทั้งสองกลับได้เข้ามาล่วงรู้ความลับของ ชิงหนิงจาง ที่พยายามปกปิดความจริงเอาไว้มานานแสนนานต่างก็ได้เข้ามาเปิดร่างแท้ของ จิ้งหนิง ว่าแท้จริงแล้วเขาคือใครกันแน่ แต่แล้งเรื่องราวและบทสรุปของซีรี่ย์เรื่องนี้จะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ สำหรับซีรี่ย์เรื่องนี้ก็ได้ออกอากาศผ่านช่องทาง WeTV และสามารับชมพร้อมกันได้แล้วในวันที่ 22 กุมภาพันธ์ 2026 โดยมีกันทั้งหมด 37 ตอนพร้อมซับไทย/พากย์ไทยให้แฟนๆได้รับชมไปพร้อมกันแล้วค่ะ   \r\n\r\n",
