    "description": "พล็อตเรื่อง ผิดเป็นกู W-W\r\n เมื่อชายหนุ่มธรรมดาที่ชีวิตเหมือนถูกสาปให้เผชิญแต่ความผิดพลาดซ้ำแล้วซ้ำเล่า ทุกการตัดสินใจของเขามักนำไปสู่ผลลัพธ์ที่เลวร้ายเกินคาด ไม่ว่าจะเป็นเรื่องความรัก หน้าที่การงาน หรือมิตรภาพ เมื่อความสัมพันธ์กับคนสำคัญพังทลาย เขาจึงเริ่มตั้งคำถามว่าแท้จริงแล้วเป็นเพราะโชคชะตา หรือเป็นเพราะตัวเขาเองอดีตที่เคยถูกฝังไว้เริ่มย้อนกลับมาหลอกหลอน พร้อมความลับบางอย่างที่เขาไม่เคยรับรู้มาก่อน กูจึงต้องเผชิญหน้ากับความจริงอันเจ็บปวด และเรียนรู้ที่จะยอมรับในสิ่งที่ตัวเองเคยทำผิดพลาด ระหว่างทาง เขาได้พบผู้คนใหม่ ๆ ที่เข้ามาเปลี่ยนมุมมองชีวิต และทำให้เขาเริ่มมองเห็นคุณค่าของตัวเอง แต่ยิ่งเขาพยายามแก้ไขอดีตมากเท่าไร กลับยิ่งทำให้สถานการณ์เลวร้ายลงอย่างไม่คาดคิด เส้นทางแห่งการไถ่บาปของเขาจึงเต็มไปด้วยความขัดแย้ง ทั้งภายในจิตใจและโลกภายนอก\r\n",
