    "sourceType": "embed",
    "description": "เรื่องย่อ-Paradise\r\n เมื่อเจ้าหน้าที่หนุ่มผู้เคร่งขรึมอย่าง ซาเวียร์ คอลลินส์ ที่พึ่งย้ายเข้ามาเป็นเจ้าหน้าที่ฝ่ายสืบสวน และเขาต้องเข้ามารับหน้าที่ในการแก้ไขเรื่องราวการฆาตกรรมของประธานาธิบดีที่กำลังปกครองเมืองเล็กๆแห่งหนึ่ง ในครั้งนี้เขาต้องใช้ความพยายามอย่างหนักเพื่อที่จะเขามาปิดคดีความวุ่นวายเหล่านี้ให้ได้ แต่ซาเวียร์  ต้องเสี่ยงต่อผู้มีอิธิพลอย่างหนัก ในความโชคร้ายเขากลับได้ภาวะนาให้ภรรยาสาวของเขาที่เสียชีวิตไปแล้วเข้ามาช่วยเหลือและพร้อมบอกเรื่องราวร้ายๆเหล่านี้ ทว่าด้วยการค้นหาเบาะแสทุกอย่างกลับต้องทำให้พยายามปกติลูกของตนเองมากยิ่งขึ้นเพราะเกิดิาการกลัวผู้ไม่หวังดีที่จพเข้ามาทำร้ายคนยที่เขารักอีกครั้ง ด้วยความสิ้นหวังกับทำให้เข้าได้มาพบการสมรู้ร่วมคิดของเหล่าผู้ก่อการร้ายระดับโลกที่พร้อมจะลงมือในทุกเมื่อ ซึ่งเขาคนนั้นกลับคือ ซินาตรา มหาเศรษฐี ผู้ไร้ตันตนแต่เขาใช้ชื่อของคนอื่นเข้ามาปิดบังตัวตนที่แท้จริงของเอง และในครั้งนี้เขากลับพร้อมที่จะเข้ามารักษาความสงบให้แก่เมืองที่เขาได้อาศัยเพื่อไม่ให้เกิดความวุ่นวายในครั้งนี้ แต่แล้วจุดจบของซีรี่ย์เรื่องนี้จะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ \r\n",
