    "videoUrl": "https://torbo007.com/embed/b1df40c0c57dded40d2759c25151734b",
    "sourceType": "embed",
    "description": "เรื่องย่อ-อย่าหวังว่าเรื่องนี้จะจบสวย\r\n  “ในค่ำคืนความรักอันแสนหวานแต่ทุกอย่างกลับจบลงด้วยเสียงเงียบที่ไม่อาจตามหาความจริงได้” บอกเล่าเรื่องราวของคู่บ่าวสาวคู่หนึ่งที่ได้ตัดสินใจแต่งงานกัน เพราะอยากเข้ามาใช้ชีวิตคู่ร่วมกันอย่างสันติ ในเมื่อสถานการณ์ที่ไม่เอือยอำนวยทั้งสองจึงตัดสินใจเดินทางเข้ามายังหมู่บ้านของพ่อแม่สามี และพร้อมบอกครอบครัวว่าทั้งสิงจะเข้ามาจัดพิธีร่วมกันในค่ำคืนนี้ แต่ดูเหมือนว่าพ่อแม่ของฝ่ายชายหนุ่มจะไม่ค่อยชอบขี้หน้าเธอมากเท่าไหร่ แต่ต้องจำยอมเพื่อลูกชายที่ เมื่อถึงเวลาและค่ำคืนงานต่งที่กำลังหวานชื่นแต่ทุกอย่างกับดับลงไปอย่างแสงเทียนเพียงเพราะเกิดเหตการณ์แปลกประหลาดขึ้นมา และดูเหมือนว่าจะไม่มีใครสามารถตามหาต้นตอของเรื่องราวปริศนาครั้งนี้ได้ และจึงทำให้พวกเขาทั้งครอบครัวกลับได้เข้ามาอยู่กับความหงาดกลัวในชั่วค่ำคืนนี้ และดูเหมือนว่าทุกอย่างจะไม่มีทางออกและกลายเป็นความหวาดกลัวอยู่เสมอมา ทว่าเรื่องราวที่น่ากลัวของครอบครัวนี้จะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ สำหรับซีรี่ย์เรื่องนี้ก็ยังคงเป็นอีกหนึ่งผลงานการสร้างสรรค์ผลงานของ “เฮลีย์ ซี. บอสตัน” ผู้กำกับมากประสบการณืที่จะเขา้มาร่วมสร้างความสนุกและความระทึกขวัญให้กับซีรี่ย์เรื่องนี้ จากความสนุกที่น่ากลัวก็สามารถรับชมไปร้อมกันได้บนช่องทาง Netflix และสามารถรับชมได้พร้อมกันในวันที่ 26 มีนาคม 2026 ตั้งแต่วันนี้เป็นต้นไป",
