    "titleTh": "Detective Hole ยอดนักสืบแฮร์รี โฮล (2026) พากย์ไทย EP.1-9",
    "titleEn": "Detective Hole ยอดนักสืบแฮร์รี โฮล (2026) พากย์ไทย EP.1-9",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/03/99-5.jpg",
