    "sourceType": "embed",
    "description": "เรื่องย่อ-ยอดนักสืบแฮร์รี โฮล\r\n เรื่องราวของ “แฮร์รี โฮล” นักสืบผู้มีชื่อเสียงด้านการไขคดีซับซ้อน ที่ต้องกลับมารับมือกับคดีฆาตกรรมต่อเนื่องที่เต็มไปด้วยเงื่อนงำอันมืดมนในเมืองใหญ่ เหยื่อแต่ละรายดูเหมือนไม่มีความเกี่ยวข้องกัน แต่หลักฐานบางอย่างกลับชี้ไปยังเครือข่ายลับที่ซ่อนอยู่เบื้องหลัง ระหว่างการสืบสวน แฮร์รีต้องเผชิญทั้งแรงกดดันจากหน่วยงานตำรวจและปีศาจในอดีตของตัวเอง คดีนี้ไม่ได้เป็นเพียงการตามล่าฆาตกรเท่านั้น แต่ยังเป็นการเปิดโปงความจริงที่อาจสั่นคลอนความเชื่อของเขา เมื่อเบาะแสเริ่มเชื่อมโยงไปถึงบุคคลที่คาดไม่ถึง เกมไล่ล่าระหว่างนักสืบและฆาตกรก็ยิ่งทวีความตึงเครียดมากขึ้น ทุกก้าวของการสืบสวนเต็มไปด้วยความเสี่ยง และยิ่งใกล้ความจริงมากเท่าไร อันตรายก็ยิ่งเข้าใกล้มากขึ้นเท่านั้น ในโลกที่ความจริงถูกปกปิดด้วยคำโกหก แฮร์รี โฮล ต้องใช้ทั้งสัญชาตญาณและไหวพริบเพื่อเปิดโปงทุกอย่าง ก่อนที่เหยื่อรายต่อไปจะปรากฏขึ้น",
