    "sourceType": "embed",
    "description": "เรื่องย่อ- เรื่องในคืนนั้น \r\n เรื่องราวเริ่มต้นจากค่ำคืนหนึ่งที่ดูเหมือนจะธรรมดา ไม่มีใครคาดคิดว่ามันจะกลายเป็นจุดเริ่มต้นของเหตุการณ์ที่พลิกชีวิตของหลายคนไปตลอดกาล เช้าวันถัดมา ตัวละครหลักตื่นขึ้นมาพร้อมความรู้สึกสับสน ราวกับมีบางช่วงเวลาของความทรงจำหายไปอย่างไร้ร่องรอย ยิ่งพยายามนึกย้อนกลับไปมากเท่าไร ก็ยิ่งพบว่ามีบางอย่างไม่ชอบมาพากลเกิดขึ้เมื่อเขาเริ่มสอบถามคนรอบตัว คำตอบที่ได้รับกลับไม่ตรงกันเลยสักอย่าง แต่ละคนต่างเล่าเรื่องในมุมของตัวเอง ราวกับว่าความจริงมีหลายเวอร์ชันซ่อนอยู่เบื้องหลังคืนลึกลับนั้น หลักฐานบางอย่างเริ่มปรากฏขึ้นทีละนิด ทว่าแทนที่จะทำให้เรื่องกระจ่าง กลับยิ่งทำให้ทุกอย่างซับซ้อนกว่าเดิม แต่แล้วบทสรุปของเรื่องราวทั้งหมดจะเป็นอย่างเราไปรับชมพร้อมๆกันค่ะ\r\n",
