    "sourceType": "embed",
    "description": "เรื่องย่อ-ภรรยาตัวป่วนของท่านแม่ทัพ ภาค 2\r\n อีกหนึ่งมินิซีรี่ย์ยอดนิยมแห่งปี (2026) กับเรื่อง “ภรรยาตัวป่วนของท่านแม่ทัพ ภาค 2” พร้อมเป็นการบอกเล่าเรื่องราว “หลี่หลาน” หญิงสาวธรรดาๆคนหนึ่งต้องมากพบเจอกับความวุ่นวายในครั้งนี้ เมื่อเธอได้ทะลุมิติเข้ามาอยู่ในหนังสือการ์ตูนในเล่มที่เธอเคยอ่าน จนกระทั่งความบังเอิญทุกอย่างกลับกลายเป็นภรรยาสาวของแม่ทัพผู้แสนเย็นชา “หวังจิ่น” ตัวละครที่เธอเคยแต่หากรู้ไม่ว่าเขากลับเป็นบุคคลที่ไม่มีใครอย่างเข้ามาใกล้ จนกระทั่งทุกอย่างกลายเป็นความสัมพันธ์ที่ยึดติดกันมากขึ้นเรื่อยๆ จนกระทั่งทุกอย่างกลายเป็นความรักที่กำลังผลิบานมากขึ้นเรื่อยๆ พร้อมเธอได้เขา้มาเปลี่ยนแปลงอาณาจักรให้เจริญรุ่งเรืองมากยิ่งขึ้น ทว่าเธอจะสามารถเปลี่ยนแปลงชีวิตนเองให้กลับมาอยู่ในยุคปัจจุบันได้หรือไม่เราไปรับชมพร้อมๆกันค่ะ \r\n",
