    "titleTh": "Silent Truth สัญญาใต้ต้นเชอร์รี่และความจริงที่ฝังกลบ (2026) ซับไทย/พากย์ไทย",
    "titleEn": "Silent Truth สัญญาใต้ต้นเชอร์รี่และความจริงที่ฝังกลบ (2026) ซับไทย/พากย์ไทย",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/01/99.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/01/99.jpg",
    "videoUrl": "https://torbo007.com/embed/f3846c6be69cb15023a8733b3ddaf228",
    "sourceType": "embed",
    "description": "เรื่องย่อ-ไซไก: ความจริงอันเงียบงัน Silent Truth\r\n พาทุกคนย้อนกลับไปเมื่อสามสิบปีก่อน เมื่อนักเรียนหญิงคนหนึ่งที่ถูกจับตามองว่าเป็นคนที่ติดอยู่ในคดีอาชญากรรมอยู่ใต้ต้นซากุระพร้อมกับเพื่อนร่วมชั้นที่สนิทกันอยู่สามคนรวมไปถึง “อิวาโมโตะ” ผู้ที่กุมความลับแต่กลับไม่สามารถบอกใครได้ จากนั้นเองเขาจึงเลือกที่จะถอยห่างออกจากเรื่องราวที่กลับกลายเป็นปมของความวุ่นวายทั้งหมดปัจจุบัน “จุนอิจิโทบินะ” ก็ได้เข้ามาทำงานเป็นนักสืบ และถูกย้ายมาประจำการในสถานีตำรวจบ้านเกิดแห่งนี้ และเมื่อเขาได้รับคดีฆาตกรรมและจึงได้มาพบกับ กิโกะ อิวาโมโตะ รักแรกของเขาอีกครั้งในฐานะผู้ร่วมกันแก้ไขคดีปริศนาครั้งนี้ และเธอกลับต้องกลายมาเป็นผู้ต้องสงสัยในครั้งนี้ แต่แล้วเรื่องราวของเธอและเขาจะเป็นอย่างไรเราไปรับลุ้นรับแรงต้านพร้อมๆกันค่ะ สำหรับซีรี่ย์เรื่องนี้ก็ออกฉายครั้งแรกบน Netflix พร้อมออกอากาศในวันที่ 13 มกราคม 2026 จำนวน 10 ตอนเท่านั้นทั้งมาในรูปแบบพากย์ไทยให้แฟนๆได้รับชมกันได้อย่างสบายๆ (แอบเมาท์เลยว่าซีรี่ย์เรื่องนี้จะพาคนดูไปดำดิ่งและดึงดราม่าสุดๆ) แต่ถ้าหากเพื่อนๆคนไหนที่ไม่ชอบซีรี่ย์เรื่องแนวนี้ก็สามารถเลือกรับชมแนวอื่นๆได้ที่ G4 ที่เราได้คัดสรรความสุขและความสุขมาไว้ที่ตรงนี้แล้ว  \r\n",
