    "description": "เรื่องย่อ ราชินีเงินปล้น\r\n บอกเล่าเรื่องราวของหญิงสาวทั้งห้าที่ต้องเข้ามาพบเจอกับเรื่องราวสุดตื่นเต้น ด้วยความบังเอิญที่ทำให้พวกเธอได้เข้ามายุ่งเกี่ยวกับเรื่องราวการก่ออาชญกรรม กลังจากที่ธนาคารทางการเงินที่พยายามผลัดดันให้พวกเขาต้องมาอยู่ในจุดมุมมืด ด้วยการตัดสินใจที่เด็ดขาดพวกเธอจึงเลือกที่จะเข้ามาปล้นธนาคาร และพร้อมที่จะเข้ามาต่อต้านความหรือก่อปัญหาการก่ออาชญากรรม ขึ้นในครั้งนี้ ด้วยแผนการที่แฉบแหลมและแผนที่ลงตัวพวกเธอจะทำอย่างไรต่อไปเราไปรับชมพร้อมๆกันค่ะ สำหรับซีรี่ย์เรื่องนี้ก็สามารถรับชมได้พร้อมกันในวันที่ 5 กุมภาพันธ์ 2026 โดยมีกันทั้งหมด 8 ตอนเพียงเท่านั้น พร้อมาในรูปแบบซับไทยให้แฟนๆได้เลือกรับชมกันแล้วบนช่องทาง Netflix หรือถ้าเพื่อนๆคนไหนที่ไม่ชอบความยุ่งยากวันนี้ทางเราได้นำความสนุกมาไว้ที่ตรงนี้แล้วกับ G4 ที่เรามีมากกว่าสามพันเรื่อง   \r\n",
