    "titleTh": "Agatha Christie’s Seven Dials ฆาตกรรมปริศนาที่เซเว่นไดอัลส์ (2026) พากย์ไทย",
    "titleEn": "Agatha Christie’s Seven Dials ฆาตกรรมปริศนาที่เซเว่นไดอัลส์ (2026) พากย์ไทย",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/01/9999.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/01/9999.jpg",
    "videoUrl": "https://torbo007.com/embed/8e4355022bb5dea04c55775081e2408d",
    "sourceType": "embed",
    "description": "เรื่องย่อ ฆาตกรรมปริศนาที่เซเว่นไดอัลส์\r\n แวะมาป้ายยากันสักนิดหนึ่ง สำหรับซีรี่ย์เรื่องใหม่ที่ถูกส่งมาจากต่างประเทศ ที่พร้อมกจะเข้ามาบอกเล่าเรื่องราวของตัวแม่ผู้มีชื่อเสียงระดับประเทศเมื่อมีงานเลี้ยงของที่บ้านหลังใหญ่แต่เธอต้องมาพบเจอกับเรื่องราวเกี่ยวดับคดีการฆาตกรรมที่น่ากลัว ด้วยความสับสนและคุ้นคิดที่ทำให้เธอต้องมาพบเจกเรื่องราวของและการเป็นอยู่ที่สั่นค่อนในตอนนี้ ทว่าเธอจุสามารถแยกรับเรื่องราวความวุ่นวายเหล่านี้ได้หรือไม่เราไปรับชมพร้อมกันค่ะ สำหรับซีรี่ย์เรื่องนี้ก็พร้อมออกอากาศในวันที่ 15 มกราคม 2026 จำนวน 5 ตอนพร้อมาในรูปแบบพากย์ไทยให้แฟนๆได้แบกรับแรงต้านไปพร้อมกันแบบสับๆ สานต่อความสนุกไปพร้อมกันพวกเราได้ที่ G4 แหล่งรวมซีรี่ย์ออนไลน์ ครบ จบ ในที่เดียว\r\n",
